export const SAMPLE_SOURCES: Record<string, string> = {"basemap":"import { ArcgisMapView, type MapLoadEventPayload } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { LONDON, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Renders a topographic basemap and reports load status. */\n\nexport function BasemapScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ basemap: 'arcGISTopographic', initialViewpoint: { center: LONDON, scale: 50_000 } }}\n        onMapLoad={({ nativeEvent }: { nativeEvent: MapLoadEventPayload }) =>\n          setStatus(`Loaded (WKID ${nativeEvent.spatialReferenceWkid})`)\n        }\n        onMapError={({ nativeEvent }) => setStatus(`Error: ${nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","webmap":"import { ArcgisMapView, type MapLoadEventPayload } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { WEB_MAP_ITEM_ID, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Loads a web map from an ArcGIS portal item id (its own basemap + layers). */\n\nexport function WebMapScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading web map…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ webMapItemId: WEB_MAP_ITEM_ID }}\n        onMapLoad={({ nativeEvent }: { nativeEvent: MapLoadEventPayload }) =>\n          setStatus(`Web map loaded (WKID ${nativeEvent.spatialReferenceWkid})`)\n        }\n        onMapError={({ nativeEvent }) => setStatus(`Error ${nativeEvent.code}: ${nativeEvent.message}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","viewpoint":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type ViewpointChangeEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { LONDON, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ViewpointScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [viewpoint, setViewpoint] = useState('Pan/zoom or tap a city…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        {PLACES.map((place) => (\n          <Button\n            key={place.name}\n            title={place.name}\n            onPress={() => {\n              mapRef.current\n                ?.setViewpoint({ center: place.center, scale: place.scale }, { durationMs: 1500 })\n                .catch(() => undefined);\n            }}\n          />\n        ))}\n      </View>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{ basemap: 'arcGISNavigation', initialViewpoint: { center: LONDON, scale: 50_000 } }}\n        onViewpointChange={({ nativeEvent }: { nativeEvent: ViewpointChangeEventPayload }) =>\n          setViewpoint(\n            `lat ${nativeEvent.center.latitude.toFixed(3)}, ` +\n              `lon ${nativeEvent.center.longitude.toFixed(3)}, ` +\n              `1:${Math.round(nativeEvent.scale).toLocaleString()}`\n          )\n        }\n      />\n      <Text style={screenStyles.status}>{viewpoint}</Text>\n    </View>\n  );\n}\n","screenshot":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type ExportImageResult,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Image, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Exports the current map view via the ref's `exportImage` and previews it. */\n\nexport function ScreenshotScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [shot, setShot] = useState<ExportImageResult | null>(null);\n  const [status, setStatus] = useState('Pan/zoom, then take a screenshot.');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title=\"Take screenshot\"\n          onPress={() => {\n            setStatus('Exporting…');\n            mapRef.current\n              ?.exportImage()\n              .then((result) => {\n                setShot(result);\n                setStatus(`Exported ${result.width}×${result.height}px`);\n              })\n              .catch((error: { code?: string; message?: string }) => {\n                setShot(null);\n                setStatus(`${error.code ?? 'Error'}: ${error.message ?? 'export failed'}`);\n              });\n          }}\n        />\n        <Text style={styles.status} numberOfLines={2}>\n          {status}\n        </Text>\n      </View>\n      <View style={screenStyles.fill}>\n        <ArcgisMapView\n          ref={mapRef}\n          style={screenStyles.fill}\n          map={{\n            basemap: 'arcGISTopographic',\n            initialViewpoint: { center: SANTA_MONICA, scale: 200_000 },\n          }}\n        />\n        {shot ? (\n          <Image\n            source={{ uri: shot.uri }}\n            style={styles.preview}\n            resizeMode=\"cover\"\n            accessibilityLabel=\"Exported map image\"\n          />\n        ) : null}\n      </View>\n    </View>\n  );\n}\n","scalebar":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Toggles the declarative `scaleBar` overlay (ArcGIS Toolkit scale bar). */\n\nexport function ScaleBarScreen({ ready }: ScreenProps) {\n  const [scaleBar, setScaleBar] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={scaleBar ? 'Hide scale bar' : 'Show scale bar'}\n          onPress={() => setScaleBar((on) => !on)}\n        />\n        <Text style={styles.status}>Pan/zoom to see the scale update.</Text>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        scaleBar={scaleBar}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 200_000 },\n        }}\n      />\n    </View>\n  );\n}\n","scaleextent":"import { ArcgisMapView, type GeographicEnvelope, type GraphicSource } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The constraints applied in the \"limits on\" state.\n\nexport function ScaleExtentScreen({ ready }: ScreenProps) {\n  const [constrained, setConstrained] = useState(true);\n  const [scale, setScale] = useState<number | null>(null);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={constrained ? 'Remove limits' : 'Apply limits'}\n          onPress={() => setConstrained((on) => !on)}\n        />\n        <View style={styles.readout}>\n          <Text style={styles.scale}>{scale === null ? 'Scale —' : `Scale ${fmt(scale)}`}</Text>\n          <Text style={styles.limits}>\n            {constrained\n              ? `Limits: zoom ${fmt(MAX_SCALE)}–${fmt(MIN_SCALE)} · ref ${fmt(REFERENCE_SCALE)}`\n              : 'Limits: none'}\n          </Text>\n          <Text style={styles.limits}>\n            {constrained\n              ? `Extent (red box): ${LA_EXTENT.minLatitude},${LA_EXTENT.minLongitude} → ${LA_EXTENT.maxLatitude},${LA_EXTENT.maxLongitude}`\n              : 'Extent: unbounded'}\n          </Text>\n        </View>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        onViewpointChange={({ nativeEvent }) => setScale(nativeEvent.scale)}\n        map={{\n          basemap: 'arcGISTopographic',\n          // Frame the whole extent box on load (just inside the 1:2,000,000 min).\n          initialViewpoint: { center: EXTENT_CENTER, scale: 1_800_000 },\n          // The extent box is always drawn so you can see where the boundary is;\n          // the constraints themselves are only applied when `constrained`.\n          graphics: [EXTENT_OUTLINE],\n          ...(constrained\n            ? {\n                minScale: MIN_SCALE,\n                maxScale: MAX_SCALE,\n                referenceScale: REFERENCE_SCALE,\n                maxExtent: LA_EXTENT,\n              }\n            : {}),\n        }}\n      />\n    </View>\n  );\n}\n","grid":"import { ArcgisMapView, type MapGrid } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function GridScreen({ ready }: ScreenProps) {\n  const [grid, setGrid] = useState<MapGrid>('latitudeLongitude');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        {GRIDS.map((g) => (\n          <Pressable\n            key={g}\n            onPress={() => setGrid(g)}\n            style={[styles.chip, grid === g && styles.chipOn]}\n          >\n            <Text style={[styles.chipText, grid === g && styles.chipTextOn]}>{LABELS[g]}</Text>\n          </Pressable>\n        ))}\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        grid={grid}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 500_000 },\n        }}\n      />\n    </View>\n  );\n}\n","background":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The background grid draws behind the basemap; zooming out past the edges of\n// the Web Mercator world makes it visible above and below the map.\n\nexport function BackgroundScreen({ ready }: ScreenProps) {\n  const [color, setColor] = useState(COLORS[0]);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Text style={styles.label}>Background:</Text>\n        {COLORS.map((c) => (\n          <Pressable\n            key={c}\n            onPress={() => setColor(c)}\n            style={[styles.swatch, { backgroundColor: c }, color === c && styles.swatchOn]}\n          />\n        ))}\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          backgroundColor: color,\n          // Zoomed far out and centered on the equator, so the background shows\n          // above and below the Web Mercator world.\n          initialViewpoint: { center: { latitude: 0, longitude: 0 }, scale: 250_000_000 },\n        }}\n      />\n    </View>\n  );\n}\n","callout":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function CalloutScreen({ ready }: ScreenProps) {\n  const [callout, setCallout] = useState<Callout | null>(null);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        onSingleTap={({ nativeEvent }) =>\n          setCallout({\n            x: nativeEvent.screenPoint.x,\n            y: nativeEvent.screenPoint.y,\n            latitude: nativeEvent.mapPoint.latitude,\n            longitude: nativeEvent.mapPoint.longitude,\n          })\n        }\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 100_000 },\n        }}\n      />\n      {callout && (\n        <View\n          pointerEvents=\"none\"\n          style={[styles.callout, { left: callout.x - 90, top: callout.y - 74 }]}\n        >\n          <Text style={styles.title}>Tapped location</Text>\n          <Text style={styles.body}>\n            {callout.latitude.toFixed(5)}, {callout.longitude.toFixed(5)}\n          </Text>\n          <View style={styles.pointer} />\n        </View>\n      )}\n      <Text style={styles.hint}>Tap the map to place a callout.</Text>\n    </View>\n  );\n}\n","location":"import {\n  ArcgisMapView,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, PermissionsAndroid, Platform, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Shows the device location (the blue dot) and, as it moves, accumulates the\n * positions from `onLocationUpdate` into a polyline — a location *history* drawn\n * with a graphic (no native trail API needed).\n */\n\nexport function LocationScreen({ ready }: ScreenProps) {\n  const [on, setOn] = useState(false);\n  const [trail, setTrail] = useState<GeographicPoint[]>([]);\n  const [last, setLast] = useState<GeographicPoint | null>(null);\n  const [denied, setDenied] = useState(false);\n\n  async function start() {\n    // Android requires the runtime permission before the data source starts; iOS\n    // prompts automatically when the ArcGIS data source starts.\n    if (Platform.OS === 'android') {\n      const result = await PermissionsAndroid.request(\n        PermissionsAndroid.PERMISSIONS.ACCESS_FINE_LOCATION\n      );\n      if (result !== PermissionsAndroid.RESULTS.GRANTED) {\n        setDenied(true);\n        return;\n      }\n    }\n    setDenied(false);\n    setTrail([]);\n    setLast(null);\n    setOn(true);\n  }\n\n  const graphics: GraphicSource[] =\n    trail.length >= 2\n      ? [\n          {\n            id: 'trail',\n            geometry: { type: 'polyline', path: trail },\n            symbol: { type: 'simpleLine', color: '#2563EB', width: 3 },\n          },\n        ]\n      : [];\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={on ? 'Stop' : 'Start location'}\n          onPress={() => (on ? setOn(false) : start())}\n        />\n        <Text style={styles.status}>\n          {denied\n            ? 'Location permission denied.'\n            : last\n              ? `${last.latitude.toFixed(5)}, ${last.longitude.toFixed(5)} · ${trail.length} pts`\n              : on\n                ? 'Waiting for a fix…'\n                : 'Off'}\n        </Text>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        locationDisplay={{ enabled: on, autoPanMode: 'recenter', showAccuracy: true }}\n        onLocationUpdate={({ nativeEvent }) => {\n          setLast(nativeEvent.position);\n          setTrail((t) => [...t, nativeEvent.position].slice(-200));\n        }}\n        map={{ basemap: 'arcGISNavigation', graphics }}\n      />\n    </View>\n  );\n}\n","floors":"/**\n * Location-subsystem screens — browse building floors, indoor positioning (IPS),\n * NMEA location, and location-driven geotriggers — mirroring the official Esri\n * samples' data.\n */\nimport {\n  ArcgisMapView,\n  type GeographicPoint,\n  type GeotriggerNotificationEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedFile } from './provisioning';\n\n// The official floor-aware / IPS web map (Esri Redlands \"Building L\").\n\nexport function FloorsScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading floor-aware map…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ webMapItemId: INDOOR_WEB_MAP, floorLevel: 1 }}\n        onMapLoad={() => setInfo('Showing floor level 1.')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","indoorpositioning":"/**\n * Location-subsystem screens — browse building floors, indoor positioning (IPS),\n * NMEA location, and location-driven geotriggers — mirroring the official Esri\n * samples' data.\n */\nimport {\n  ArcgisMapView,\n  type GeographicPoint,\n  type GeotriggerNotificationEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedFile } from './provisioning';\n\n// The official floor-aware / IPS web map (Esri Redlands \"Building L\").\n\nexport function IndoorPositioningScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading IPS map…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ webMapItemId: INDOOR_WEB_MAP }}\n        locationDisplay={{ enabled: true, dataSource: 'indoors', autoPanMode: 'recenter' }}\n        onMapLoad={() => setInfo('IPS positioning started (needs an IPS-enabled venue).')}\n        onLocationUpdate={(e) =>\n          setInfo(\n            `IPS: ${e.nativeEvent.position.latitude.toFixed(5)}, ` +\n              `${e.nativeEvent.position.longitude.toFixed(5)}`\n          )\n        }\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","nmea":"/**\n * Location-subsystem screens — browse building floors, indoor positioning (IPS),\n * NMEA location, and location-driven geotriggers — mirroring the official Esri\n * samples' data.\n */\nimport {\n  ArcgisMapView,\n  type GeographicPoint,\n  type GeotriggerNotificationEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedFile } from './provisioning';\n\n// The official floor-aware / IPS web map (Esri Redlands \"Building L\").\n\nexport function NmeaScreen({ ready }: ScreenProps) {\n  // The official sample's Redlands NMEA track (a portal item raw file).\n  const { path, status } = useProvisionedFile('d5bad9f4fee9483791e405880fb466da', 'Redlands.nmea');\n  const [info, setInfo] = useState('Loading NMEA source…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISNavigation',\n          initialViewpoint: { center: { latitude: 34.056, longitude: -117.196 }, scale: 10_000 },\n        }}\n        locationDisplay={{\n          enabled: true,\n          dataSource: 'nmea',\n          nmeaSentencesPath: path,\n          autoPanMode: 'recenter',\n        }}\n        onLocationUpdate={(e) =>\n          setInfo(\n            `NMEA fix: ${e.nativeEvent.position.latitude.toFixed(5)}, ` +\n              `${e.nativeEvent.position.longitude.toFixed(5)}`\n          )\n        }\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","geotriggers":"/**\n * Location-subsystem screens — browse building floors, indoor positioning (IPS),\n * NMEA location, and location-driven geotriggers — mirroring the official Esri\n * samples' data.\n */\nimport {\n  ArcgisMapView,\n  type GeographicPoint,\n  type GeotriggerNotificationEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedFile } from './provisioning';\n\n// The official floor-aware / IPS web map (Esri Redlands \"Building L\").\n\nexport function GeotriggerScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Move into a fence to trigger a notification.');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: POIS[0].point, scale: 5_000 },\n          graphics: POIS.map((poi) => ({\n            id: poi.id,\n            geometry: { type: 'point', point: poi.point },\n            symbol: { type: 'simpleMarker', style: 'circle', color: '#2E86DE', size: 12 },\n          })),\n          geotriggers: POIS.map((poi) => ({\n            id: poi.id,\n            bufferMeters: 50,\n            ruleType: 'enterOrExit',\n          })),\n        }}\n        locationDisplay={{ enabled: true, autoPanMode: 'recenter' }}\n        onGeotriggerNotification={(e: { nativeEvent: GeotriggerNotificationEventPayload }) =>\n          setInfo(`${e.nativeEvent.action} ${e.nativeEvent.geotriggerId}: ${e.nativeEvent.message}`)\n        }\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","monitorstatus":"import {\n  ArcgisMapView,\n  type DrawStatus,\n  type LayerViewStatus,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function MonitorStatusScreen({ ready }: ScreenProps) {\n  const [drawStatus, setDrawStatus] = useState<DrawStatus>('completed');\n  const [layerStatuses, setLayerStatuses] = useState<LayerViewStatus[]>([]);\n  const [visible, setVisible] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button title={visible ? 'Hide layer' : 'Show layer'} onPress={() => setVisible((v) => !v)} />\n        <View style={styles.readout}>\n          <Text style={styles.line}>\n            Draw: {drawStatus === 'inProgress' ? 'Drawing…' : 'Idle'}\n          </Text>\n          <Text style={styles.line}>\n            Layer state: {layerStatuses.length ? layerStatuses.join(', ') : '—'}\n          </Text>\n          <Text style={styles.hint}>Long-press the map for the magnifier.</Text>\n        </View>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        onDrawStatusChange={({ nativeEvent }) => setDrawStatus(nativeEvent.status)}\n        onLayerViewStateChange={({ nativeEvent }) => {\n          if (nativeEvent.layerId === LAYER_ID) setLayerStatuses(nativeEvent.statuses);\n        }}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 63.5, longitude: -150.0 }, scale: 12_000_000 },\n          featureLayers: [{ id: LAYER_ID, url: PARKS_URL, visible }],\n        }}\n      />\n    </View>\n  );\n}\n","rotation":"import { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function RotationScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [rotation, setRotation] = useState(0);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        {ANGLES.map((deg) => (\n          <Button\n            key={deg}\n            title={`${deg}°`}\n            onPress={() =>\n              mapRef.current\n                ?.setViewpoint({ center: CENTER, scale: 100_000, rotation: deg }, { durationMs: 1000 })\n                .catch(() => undefined)\n            }\n          />\n        ))}\n      </View>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{ basemap: 'arcGISTopographic', initialViewpoint: { center: CENTER, scale: 100_000 } }}\n        onViewpointChange={({ nativeEvent }) => setRotation(nativeEvent.rotation)}\n      />\n      <Text style={screenStyles.status}>Heading: {Math.round(rotation)}° clockwise from north</Text>\n    </View>\n  );\n}\n","overview":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function OverviewMapScreen({ ready }: ScreenProps) {\n  const insetRef = useRef<ArcgisMapViewRef>(null);\n  const [center, setCenter] = useState<GeographicPoint>(START);\n  const [scale, setScale] = useState(100_000);\n\n  const marker: GraphicSource = {\n    id: 'here',\n    geometry: { type: 'point', point: center },\n    symbol: { type: 'simpleMarker', color: '#DC2626', size: 10, style: 'circle' },\n  };\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ basemap: 'arcGISTopographic', initialViewpoint: { center: START, scale: 100_000 } }}\n        onViewpointChange={({ nativeEvent }) => {\n          setCenter(nativeEvent.center);\n          setScale(nativeEvent.scale);\n          insetRef.current\n            ?.setViewpoint({ center: nativeEvent.center, scale: nativeEvent.scale * OVERVIEW_FACTOR })\n            .catch(() => undefined);\n        }}\n      />\n      <View style={styles.inset}>\n        <ArcgisMapView\n          ref={insetRef}\n          style={screenStyles.fill}\n          interactionEnabled={false}\n          map={{\n            basemap: 'arcGISLightGray',\n            initialViewpoint: { center: START, scale: 100_000 * OVERVIEW_FACTOR },\n            graphics: [marker],\n          }}\n        />\n      </View>\n      <Text style={styles.badge}>Overview · 1:{Math.round(scale * OVERVIEW_FACTOR).toLocaleString()}</Text>\n    </View>\n  );\n}\n","bookmarks":"import { ArcgisMapView, type ArcgisMapViewRef, type Viewpoint } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function BookmarksScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [bookmarks, setBookmarks] = useState<Bookmark[]>(INITIAL);\n  const [current, setCurrent] = useState<Viewpoint>(INITIAL[0].viewpoint);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ScrollView horizontal style={styles.barScroll} contentContainerStyle={styles.bar} showsHorizontalScrollIndicator={false}>\n        {bookmarks.map((b) => (\n          <Pressable\n            key={b.name}\n            style={styles.chip}\n            onPress={() => mapRef.current?.setViewpoint(b.viewpoint, { durationMs: 1500 }).catch(() => undefined)}\n          >\n            <Text style={styles.chipText}>{b.name}</Text>\n          </Pressable>\n        ))}\n        <Pressable\n          style={[styles.chip, styles.add]}\n          onPress={() => setBookmarks((bs) => [...bs, { name: `Pin ${bs.length + 1}`, viewpoint: current }])}\n        >\n          <Text style={[styles.chipText, styles.addText]}>+ Add current</Text>\n        </Pressable>\n      </ScrollView>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{ basemap: 'arcGISImagery', initialViewpoint: INITIAL[0].viewpoint }}\n        onViewpointChange={({ nativeEvent }) =>\n          setCurrent({ center: nativeEvent.center, scale: nativeEvent.scale })\n        }\n      />\n    </View>\n  );\n}\n","basemapparams":"import { ArcgisMapView, type BasemapWorldview } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Kashmir: a region whose boundaries differ by worldview, so the change is\n// visible when you switch between China / India / Pakistan.\n\nexport function BasemapParametersScreen({ ready }: ScreenProps) {\n  const [worldview, setWorldview] = useState<BasemapWorldview | 'default'>('default');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ScrollView horizontal style={styles.barScroll} contentContainerStyle={styles.bar} showsHorizontalScrollIndicator={false}>\n        {WORLDVIEWS.map((w) => (\n          <Pressable\n            key={w}\n            style={[styles.chip, worldview === w && styles.chipActive]}\n            onPress={() => setWorldview(w)}\n          >\n            <Text style={[styles.chipText, worldview === w && styles.chipTextActive]}>{w}</Text>\n          </Pressable>\n        ))}\n      </ScrollView>\n      <Text style={styles.status}>Worldview: {worldview}</Text>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: KASHMIR, scale: 12_000_000 },\n          ...(worldview === 'default' ? {} : { basemapStyleParameters: { worldview } }),\n        }}\n      />\n    </View>\n  );\n}\n","spatialref":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// World Bonne — a pseudo-conic projection whose curved graticule makes the\n// non-Web-Mercator reference obvious.\n\nexport function SpatialReferenceScreen({ ready }: ScreenProps) {\n  const [bonne, setBonne] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button title={bonne ? 'Use Web Mercator' : 'Use World Bonne'} onPress={() => setBonne((b) => !b)} />\n        <Text style={styles.status}>\n          {bonne ? `Spatial reference: World Bonne (${WORLD_BONNE_WKID})` : 'Spatial reference: Web Mercator'}\n        </Text>\n      </View>\n      <ArcgisMapView\n        // Recreate the map when the reference changes (spatial reference is baked\n        // in at creation).\n        key={bonne ? 'bonne' : 'mercator'}\n        style={screenStyles.fill}\n        map={{\n          ...(bonne\n            ? { spatialReferenceWkid: WORLD_BONNE_WKID }\n            : { basemap: 'arcGISLightGray' }),\n          layers: [{ id: 'cities', type: 'mapImage', url: WORLD_CITIES_URL }],\n          initialViewpoint: { center: { latitude: 20, longitude: 0 }, scale: 300_000_000 },\n        }}\n      />\n    </View>\n  );\n}\n","basemapgallery":"import {\n  ArcgisMapView,\n  BASEMAP_STYLES,\n  getBasemapStyles,\n  type BasemapStyle,\n  type BasemapStyleInfo,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Image, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The service reports a style's name (e.g. \"ArcGIS Imagery\"); match it to the\n// supported BasemapStyle union by comparing letters-only, case-insensitively\n// (\"ArcGIS Imagery\" → \"arcgisimagery\" ≡ \"arcGISImagery\").\n\nexport function BasemapGalleryScreen({ ready }: ScreenProps) {\n  const [styles_, setStyles] = useState<BasemapStyleInfo[]>([]);\n  const [selected, setSelected] = useState<BasemapStyle>('arcGISTopographic');\n  const [error, setError] = useState<string | null>(null);\n\n  useEffect(() => {\n    if (!ready) return;\n    getBasemapStyles()\n      .then(setStyles)\n      .catch((e) => setError(e?.message ?? String(e)));\n  }, [ready]);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ basemap: selected, initialViewpoint: { center: { latitude: 40, longitude: -100 }, scale: 50_000_000 } }}\n      />\n      <View style={styles.tray}>\n        <Text style={styles.title}>\n          {error ? `Error: ${error}` : `${styles_.length} styles · tap a supported one to apply`}\n        </Text>\n        <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={styles.row}>\n          {styles_.map((s) => {\n            const mapped = toBasemapStyle(s.styleName);\n            return (\n              <Pressable\n                key={s.styleName}\n                disabled={!mapped}\n                onPress={() => mapped && setSelected(mapped)}\n                style={[styles.cell, !mapped && styles.disabled, mapped === selected && styles.active]}\n              >\n                {s.thumbnailUri ? (\n                  <Image source={{ uri: s.thumbnailUri }} style={styles.thumb} />\n                ) : (\n                  <View style={[styles.thumb, styles.noThumb]} />\n                )}\n                <Text style={styles.name} numberOfLines={1}>\n                  {s.name}\n                </Text>\n              </Pressable>\n            );\n          })}\n        </ScrollView>\n      </View>\n    </View>\n  );\n}\n","coordinates":"import { ArcgisMapView, formatCoordinates, type CoordinateFormats } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function CoordinatesScreen({ ready }: ScreenProps) {\n  const [formats, setFormats] = useState<CoordinateFormats | null>(null);\n  const [error, setError] = useState<string | null>(null);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        onSingleTap={async ({ nativeEvent }) => {\n          try {\n            setError(null);\n            setFormats(await formatCoordinates(nativeEvent.mapPoint));\n          } catch (e) {\n            setError(e instanceof Error ? e.message : String(e));\n          }\n        }}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 100_000 },\n        }}\n      />\n      <View style={styles.panel}>\n        {error && <Text style={styles.error}>{error}</Text>}\n        {!formats && !error && <Text style={styles.hint}>Tap the map to read coordinates.</Text>}\n        {formats &&\n          ROWS.map((r) => (\n            <View key={r.key} style={styles.row}>\n              <Text style={styles.rowLabel}>{r.label}</Text>\n              <Text style={styles.rowValue}>{formats[r.key]}</Text>\n            </View>\n          ))}\n      </View>\n    </View>\n  );\n}\n","layers":"import { ArcgisMapView, type MapLoadEventPayload } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Renders a basemap with an ArcGIS feature service layer (reconciled by id). */\n\nexport function FeatureLayerScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 120_000 },\n          featureLayers: [{ id: 'trailheads', url: TRAILHEADS_URL }],\n        }}\n        onMapLoad={({ nativeEvent }: { nativeEvent: MapLoadEventPayload }) =>\n          setStatus(`Map loaded (WKID ${nativeEvent.spatialReferenceWkid}); trailheads layer added`)\n        }\n        onMapError={({ nativeEvent }) => setStatus(`Error ${nativeEvent.code}: ${nativeEvent.message}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","layertypes":"import { ArcgisMapView, type ArcgisLayerSource } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function LayerTypesScreen({ ready }: ScreenProps) {\n  const [key, setKey] = useState('tiled');\n  const active = LAYERS.find((l) => l.key === key) ?? LAYERS[0];\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ScrollView\n        horizontal\n        style={styles.barScroll}\n        contentContainerStyle={styles.bar}\n        showsHorizontalScrollIndicator={false}\n      >\n        {LAYERS.map((l) => (\n          <Pressable\n            key={l.key}\n            onPress={() => setKey(l.key)}\n            style={[styles.chip, key === l.key && styles.chipOn]}\n          >\n            <Text style={[styles.chipText, key === l.key && styles.chipTextOn]}>{l.label}</Text>\n          </Pressable>\n        ))}\n      </ScrollView>\n      <ArcgisMapView\n        // Remount per selection so the layer's viewpoint is applied.\n        key={active.key}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: active.viewpoint,\n          layers: [active.layer],\n        }}\n      />\n    </View>\n  );\n}\n","featurecollection":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A public ArcGIS portal item whose data is a feature collection.\n\nexport function FeatureCollectionScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <ArcgisMapView\n      style={screenStyles.fill}\n      map={{\n        basemap: 'arcGISOceans',\n        initialViewpoint: { center: { latitude: 32.62, longitude: -101.34 }, scale: 60_000_000 },\n        layers: [{ id: 'fc', type: 'featureCollection', portalItemId: FEATURE_COLLECTION_ITEM }],\n      }}\n    />\n  );\n}\n","grouplayer":"import { ArcgisMapView, type ArcgisLayerSource } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A group of two tiled reference layers over the continental US, toggled as one.\n\nexport function GroupLayerScreen({ ready }: ScreenProps) {\n  const [visible, setVisible] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button title={visible ? 'Hide group' : 'Show group'} onPress={() => setVisible((v) => !v)} />\n        <Text style={styles.status}>Group “Reference”: {visible ? 'shown' : 'hidden'} (2 sublayers)</Text>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 50_000_000 },\n          layers: [{ ...GROUP, visible }],\n        }}\n      />\n    </View>\n  );\n}\n","kmlnetworklink":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlNetworkLinkScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading KML network links…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISDarkGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 30_000_000 },\n          layers: [{ id: 'kml-network', type: 'kml', url: NETWORK_LINK_KML }],\n        }}\n        onMapLoad={() => setInfo('KML network links loaded (they refresh on their own interval).')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","kmlidentify":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlIdentifyScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [info, setInfo] = useState('Tap a KML feature to identify it.');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISDarkGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 30_000_000 },\n          layers: [{ id: 'kml-identify', type: 'kml', url: IDENTIFY_KML }],\n        }}\n        onSingleTap={async (e) => {\n          try {\n            const results = await mapRef.current?.identify({ screenPoint: e.nativeEvent.screenPoint });\n            const kml = (results ?? []).filter((r) => r.sourceId === 'kml-identify');\n            setInfo(kml.length ? `Identified ${kml.length} KML feature(s).` : 'No KML feature here.');\n          } catch (error) {\n            setInfo(`identify failed: ${(error as { code?: string }).code ?? 'error'}`);\n          }\n        }}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","mosaicraster":"/**\n * Layers-depth screens — apply a mosaic rule to an image-service raster,\n * identify a raster cell, and control annotation sublayer visibility.\n */\nimport { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official \"Apply mosaic rule to rasters\" sample's mosaic image service.\n\nexport function MosaicRasterScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading mosaicked raster…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImageryStandard',\n          initialViewpoint: { center: { latitude: 49.44, longitude: 11.85 }, scale: 20_000 },\n          layers: [\n            {\n              id: 'mosaic',\n              type: 'raster',\n              url: MOSAIC_SERVICE,\n              mosaicRule: { method: 'northwest', operation: 'first' },\n            },\n          ],\n        }}\n        onMapLoad={() => setInfo('Mosaic rule applied (north-west ordering).')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","identifyrastercell":"/**\n * Layers-depth screens — apply a mosaic rule to an image-service raster,\n * identify a raster cell, and control annotation sublayer visibility.\n */\nimport { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official \"Apply mosaic rule to rasters\" sample's mosaic image service.\n\nexport function IdentifyRasterCellScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [info, setInfo] = useState('Tap the raster to identify a cell.');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISDarkGray',\n          initialViewpoint: { center: { latitude: 35.24, longitude: -80.83 }, scale: 30_000 },\n          layers: [{ id: 'raster-cell', type: 'raster', url: RASTER_CELL_SERVICE }],\n        }}\n        onSingleTap={async (e) => {\n          try {\n            const results = await mapRef.current?.identify({ screenPoint: e.nativeEvent.screenPoint });\n            const cell = (results ?? []).find((r) => r.sourceId === 'raster-cell');\n            const values = cell ? Object.entries(cell.attributes ?? {}) : [];\n            setInfo(\n              values.length\n                ? `Cell: ${values.map(([k, v]) => `${k}=${v}`).join(', ')}`\n                : 'No raster cell here.'\n            );\n          } catch (error) {\n            setInfo(`identify failed: ${(error as { code?: string }).code ?? 'error'}`);\n          }\n        }}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","annotationsublayer":"/**\n * Layers-depth screens — apply a mosaic rule to an image-service raster,\n * identify a raster cell, and control annotation sublayer visibility.\n */\nimport { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official \"Apply mosaic rule to rasters\" sample's mosaic image service.\n\nexport function AnnotationSublayerScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading annotation layer…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 55.94, longitude: -2.83 }, scale: 40_000 },\n          layers: [\n            {\n              id: 'annotation',\n              type: 'annotation',\n              url: ANNOTATION_SERVICE,\n              sublayerVisibility: [\n                { name: 'Open', visible: true },\n                { name: 'Closed', visible: false },\n              ],\n            },\n          ],\n        }}\n        onMapLoad={() => setInfo('Annotation layer loaded; \"Closed\" sublayer hidden.')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","dynamicentitylayer":"/**\n * Dynamic-entity (real-time) screens — show a dynamic entity layer streaming\n * from a stream service, query its current entities, and replay a custom feed\n * from a local file.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, queryDynamicEntities } from 'expo-arcgis-maps-sdk';\nimport { useMemo, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official real-time samples' vehicle stream service.\n\nexport function DynamicEntityLayerScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Connecting to the stream service…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISDarkGray',\n          initialViewpoint: { center: { latitude: 40.559, longitude: -74.15 }, scale: 150_000 },\n          layers: [{ id: 'vehicles', type: 'dynamicEntity', url: STREAM_SERVICE }],\n        }}\n        onMapLoad={() => setInfo('Streaming live vehicle positions.')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","customdynamicentity":"/**\n * Dynamic-entity (real-time) screens — show a dynamic entity layer streaming\n * from a stream service, query its current entities, and replay a custom feed\n * from a local file.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, queryDynamicEntities } from 'expo-arcgis-maps-sdk';\nimport { useMemo, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official real-time samples' vehicle stream service.\n\nexport function CustomDynamicEntityScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Replaying local observations…');\n  const observationsPath = useMemo(() => {\n    try {\n      return writeObservationsFile();\n    } catch (error) {\n      setInfo(`Could not write observations file: ${String(error)}`);\n      return null;\n    }\n  }, []);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!observationsPath) {\n    return <Centered text={info} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISDarkGray',\n          initialViewpoint: { center: { latitude: 40.69, longitude: -74.04 }, scale: 120_000 },\n          layers: [\n            {\n              id: 'custom-vessels',\n              type: 'dynamicEntity',\n              customFeed: {\n                observationsPath,\n                entityIdField: 'MMSI',\n                longitudeField: 'longitude',\n                latitudeField: 'latitude',\n                observationsPerSecond: 15,\n              },\n            },\n          ],\n        }}\n        onMapLoad={() => setInfo('Replaying vessel tracks from a local file.')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","tiledbasemap":"/**\n * Basemap-from-layer screens — a basemap built from a single base layer rather\n * than a named style: a tiled map service, and a vector tile layer with a custom\n * style loaded from a portal item.\n */\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A tiled ArcGIS map service used directly as the basemap.\n\nexport function TiledBasemapScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading tiled basemap…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemapLayer: { type: 'tiled', url: WORLD_IMAGERY_TILED },\n          initialViewpoint: { center: { latitude: 34.05, longitude: -118.24 }, scale: 600_000 },\n        }}\n        onMapLoad={() => setStatus('Basemap from a tiled map service.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","vtlcustomstyle":"/**\n * Basemap-from-layer screens — a basemap built from a single base layer rather\n * than a named style: a tiled map service, and a vector tile layer with a custom\n * style loaded from a portal item.\n */\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A tiled ArcGIS map service used directly as the basemap.\n\nexport function VectorTiledCustomStyleScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading custom vector tile style…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemapLayer: { type: 'vectorTiled', itemId: CUSTOM_VTL_ITEM },\n          initialViewpoint: { center: { latitude: 37.78, longitude: -122.42 }, scale: 500_000 },\n        }}\n        onMapLoad={() => setStatus('Basemap from a custom vector tile style.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","enc":"/**\n * `Configure electronic navigational charts` — displays an S-57/ENC layer from\n * a local ENC exchange set, with the process-wide hydrography resources the ENC\n * renderer requires.\n *\n * The ENC exchange set and the S-57/S-52 hydrography resources are large data\n * packages that ship with ArcGIS, not with this repo, so they must be placed on\n * the device first (the official sample bundles them as on-demand resources).\n * Put them under the app document directory as documented below; until then the\n * screen shows the oceans basemap and a provisioning notice.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, type EncLayerSource } from 'expo-arcgis-maps-sdk';\nimport { useMemo, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function EncScreen({ ready }: ScreenProps) {\n  const resolved = useMemo(resolveEncData, []);\n  const [status, setStatus] = useState(resolved.note);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          // The official sample's oceans basemap + viewpoint over the ENC cells.\n          basemap: 'arcGISOceans',\n          initialViewpoint: { center: { latitude: -32.5, longitude: 60.95 }, scale: 67_000 },\n          layers: resolved.layer ? [resolved.layer] : [],\n        }}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","servicebrowser":"import {\n  getServiceLayers,\n  type BrowsableServiceType,\n  type ServiceLayerInfo,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { ActivityIndicator, Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ServiceBrowserScreen({ ready }: ScreenProps) {\n  const [selected, setSelected] = useState<BrowsableServiceType | null>(null);\n  const [layers, setLayers] = useState<ServiceLayerInfo[]>([]);\n  const [loading, setLoading] = useState(false);\n  const [error, setError] = useState<string | null>(null);\n\n  async function browse(svc: (typeof SERVICES)[number]) {\n    setSelected(svc.type);\n    setLayers([]);\n    setError(null);\n    setLoading(true);\n    try {\n      setLayers(await getServiceLayers({ type: svc.type, url: svc.url }));\n    } catch (e) {\n      setError((e as { message?: string })?.message ?? String(e));\n    } finally {\n      setLoading(false);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        {SERVICES.map((svc) => (\n          <Pressable\n            key={svc.type}\n            style={[styles.chip, selected === svc.type && styles.chipActive]}\n            onPress={() => browse(svc)}\n          >\n            <Text style={[styles.chipText, selected === svc.type && styles.chipTextActive]}>\n              {svc.label}\n            </Text>\n          </Pressable>\n        ))}\n      </View>\n      <Text style={styles.status}>\n        {loading\n          ? 'Browsing…'\n          : error\n            ? `Error: ${error}`\n            : selected\n              ? `${layers.length} layers/collections`\n              : 'Pick a service to browse.'}\n      </Text>\n      {loading ? (\n        <ActivityIndicator style={styles.spinner} />\n      ) : (\n        <ScrollView style={screenStyles.fill} contentContainerStyle={styles.list}>\n          {layers.map((l) => (\n            <View key={l.id} style={styles.row}>\n              <Text style={styles.title}>{l.title}</Text>\n              <Text style={styles.id}>{l.id}</Text>\n            </View>\n          ))}\n        </ScrollView>\n      )}\n    </View>\n  );\n}\n","graphics":"import { ArcgisMapView, type MapLoadEventPayload } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { LONDON, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Renders point / polyline / polygon graphics with simple symbols. */\n\nexport function GraphicsScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: LONDON, scale: 40_000 },\n          graphics: [\n            {\n              id: 'poly',\n              geometry: {\n                type: 'polygon',\n                ring: [\n                  { latitude: 51.406, longitude: -0.312 },\n                  { latitude: 51.419, longitude: -0.312 },\n                  { latitude: 51.419, longitude: -0.29 },\n                  { latitude: 51.406, longitude: -0.29 },\n                ],\n              },\n              symbol: {\n                type: 'simpleFill',\n                color: '#12965940',\n                outline: { type: 'simpleLine', color: '#129659', width: 2 },\n              },\n            },\n            {\n              id: 'line',\n              geometry: {\n                type: 'polyline',\n                path: [\n                  { latitude: 51.404, longitude: -0.318 },\n                  { latitude: 51.414, longitude: -0.295 },\n                  { latitude: 51.421, longitude: -0.305 },\n                ],\n              },\n              symbol: { type: 'simpleLine', color: '#005ea2', width: 3, style: 'dash' },\n            },\n            {\n              id: 'pt',\n              geometry: { type: 'point', point: LONDON },\n              symbol: { type: 'simpleMarker', color: '#d83933', size: 14, style: 'circle' },\n            },\n            {\n              // Multilayer polyline: a wide dark casing under a thin white center line.\n              id: 'multiline',\n              geometry: {\n                type: 'polyline',\n                path: [\n                  { latitude: 51.408, longitude: -0.318 },\n                  { latitude: 51.408, longitude: -0.29 },\n                ],\n              },\n              symbol: {\n                type: 'multilayerPolyline',\n                strokeLayers: [\n                  { color: '#1b1b1b', widthPoints: 10 },\n                  { color: '#ffffff', widthPoints: 3 },\n                ],\n              },\n            },\n          ],\n        }}\n        onMapLoad={({ nativeEvent }: { nativeEvent: MapLoadEventPayload }) =>\n          setStatus(`Loaded (WKID ${nativeEvent.spatialReferenceWkid}); marker + line + polygon`)\n        }\n        onMapError={({ nativeEvent }) => setStatus(`Error ${nativeEvent.code}: ${nativeEvent.message}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","geometrytypes":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Styles all three geometry types at once — a marker (point), a line (polyline),\n * and a filled area (polygon) — each with a distinct simple symbol.\n */\n\nexport function GeometryTypesScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  const { latitude, longitude } = SANTA_MONICA;\n  return (\n    <ArcgisMapView\n      style={screenStyles.fill}\n      map={{\n        basemap: 'arcGISTopographic',\n        initialViewpoint: { center: SANTA_MONICA, scale: 120_000 },\n        graphics: [\n          {\n            id: 'point',\n            geometry: { type: 'point', point: SANTA_MONICA },\n            symbol: { type: 'simpleMarker', color: '#DC2626', size: 16, style: 'diamond' },\n          },\n          {\n            id: 'line',\n            geometry: {\n              type: 'polyline',\n              path: [\n                { latitude: latitude + 0.03, longitude: longitude - 0.05 },\n                { latitude: latitude + 0.01, longitude: longitude + 0.02 },\n                { latitude: latitude + 0.04, longitude: longitude + 0.06 },\n              ],\n            },\n            symbol: { type: 'simpleLine', color: '#2563EB', width: 4, style: 'dash' },\n          },\n          {\n            id: 'polygon',\n            geometry: {\n              type: 'polygon',\n              ring: [\n                { latitude: latitude - 0.02, longitude: longitude - 0.05 },\n                { latitude: latitude - 0.05, longitude: longitude - 0.03 },\n                { latitude: latitude - 0.05, longitude: longitude + 0.03 },\n                { latitude: latitude - 0.02, longitude: longitude + 0.05 },\n              ],\n            },\n            symbol: {\n              type: 'simpleFill',\n              color: '#16A34A55',\n              outline: { type: 'simpleLine', color: '#166534', width: 2 },\n            },\n          },\n        ],\n      }}\n    />\n  );\n}\n","geometryops":"import {\n  ArcgisMapView,\n  bufferGeometry,\n  planarBufferGeometry,\n  clipGeometry,\n  combineGeometries,\n  convexHull,\n  cutGeometry,\n  geometryRelationships,\n  projectPoint,\n  type ArcgisGeometry,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Two overlapping squares and a scatter of points around Santa Monica.\n\nexport function GeometryOpsScreen({ ready }: ScreenProps) {\n  const [result, setResult] = useState<GraphicSource[]>([]);\n  const [status, setStatus] = useState('Run a geometry operation.');\n\n  async function run(op: (typeof OPS)[number]) {\n    try {\n      const { status: s, result: geometries, graphics } = await op.run();\n      setStatus(s);\n      setResult(graphics ?? (geometries ? toGraphics(geometries) : []));\n    } catch (e) {\n      setStatus(e instanceof Error ? e.message : String(e));\n      setResult([]);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ScrollView horizontal style={styles.barScroll} contentContainerStyle={styles.bar} showsHorizontalScrollIndicator={false}>\n        {OPS.map((op) => (\n          <Pressable key={op.key} onPress={() => run(op)} style={styles.chip}>\n            <Text style={styles.chipText}>{op.key}</Text>\n          </Pressable>\n        ))}\n      </ScrollView>\n      <Text style={styles.status}>{status}</Text>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: SANTA_MONICA, scale: 400_000 },\n          graphics: [\n            { id: 'a', geometry: polyA, symbol: { type: 'simpleFill', color: '#DC262622', outline: { type: 'simpleLine', color: '#DC2626', width: 2 } } },\n            { id: 'b', geometry: polyB, symbol: { type: 'simpleFill', color: '#2563EB22', outline: { type: 'simpleLine', color: '#2563EB', width: 2 } } },\n            ...result,\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","geodesic":"import {\n  ArcgisMapView,\n  geodesicPath,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function GeodesicScreen({ ready }: ScreenProps) {\n  const [graphics, setGraphics] = useState<GraphicSource[]>([endpoint('a', LONDON), endpoint('b', TOKYO)]);\n  const [status, setStatus] = useState('Computing geodesic path…');\n\n  useEffect(() => {\n    if (!ready) return;\n    geodesicPath(LONDON, TOKYO)\n      .then((path) => {\n        setGraphics([\n          endpoint('a', LONDON),\n          endpoint('b', TOKYO),\n          { id: 'geodesic', geometry: path, symbol: { type: 'simpleLine', color: '#2563EB', width: 3 } },\n          {\n            id: 'straight',\n            geometry: { type: 'polyline', path: [LONDON, TOKYO] },\n            symbol: { type: 'simpleLine', color: '#9CA3AF', width: 2, style: 'dash' },\n          },\n        ]);\n        setStatus('Blue: geodesic (great-circle). Grey dashes: straight line.');\n      })\n      .catch((e) => setStatus((e as { message?: string })?.message ?? String(e)));\n  }, [ready]);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <Text style={styles.status}>{status}</Text>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 55, longitude: 65 }, scale: 120_000_000 },\n          graphics,\n        }}\n      />\n    </View>\n  );\n}\n","geometryrefine":"import {\n  ArcgisMapView,\n  densifyGeometry,\n  generalizeGeometry,\n  nearestVertex,\n  simplifyGeometry,\n  type ArcgisGeometry,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A coarse, jagged polyline across the US whose vertex count visibly changes\n// under densify / generalize.\n\nexport function GeometryRefineScreen({ ready }: ScreenProps) {\n  const [graphics, setGraphics] = useState<GraphicSource[]>([\n    { id: 'orig', geometry: LINE, symbol: orig },\n    ...vertices(LINE, '#6B7280'),\n  ]);\n  const [status, setStatus] = useState('Pick an operation.');\n\n  const OPS = [\n    {\n      key: 'Densify',\n      run: async () => {\n        const g = await densifyGeometry(LINE, 1.5);\n        const n = g.type === 'polyline' ? g.path.length : 0;\n        setStatus(`Densify: 6 → ${n} vertices`);\n        return [{ id: 'orig', geometry: LINE, symbol: orig }, { id: 'res', geometry: g, symbol: result }, ...vertices(g, '#2563EB')];\n      },\n    },\n    {\n      key: 'Generalize',\n      run: async () => {\n        const g = await generalizeGeometry(LINE, 3);\n        const n = g.type === 'polyline' ? g.path.length : 0;\n        setStatus(`Generalize: 6 → ${n} vertices`);\n        return [{ id: 'orig', geometry: LINE, symbol: orig }, { id: 'res', geometry: g, symbol: result }, ...vertices(g, '#2563EB')];\n      },\n    },\n    {\n      key: 'Simplify',\n      run: async () => {\n        const g = await simplifyGeometry(BOWTIE);\n        setStatus('Simplify: repaired the self-intersecting polygon.');\n        return [{ id: 'res', geometry: g, symbol: fill }];\n      },\n    },\n    {\n      key: 'Nearest vertex',\n      run: async () => {\n        const r = await nearestVertex(LINE, TAP_POINT);\n        setStatus(`Nearest vertex: ${r.point.latitude.toFixed(1)}, ${r.point.longitude.toFixed(1)}`);\n        return [\n          { id: 'orig', geometry: LINE, symbol: orig },\n          ...vertices(LINE, '#9CA3AF'),\n          { id: 'query', geometry: { type: 'point' as const, point: TAP_POINT }, symbol: { type: 'simpleMarker' as const, color: '#DC2626', size: 12, style: 'x' as const } },\n          { id: 'near', geometry: { type: 'point' as const, point: r.point }, symbol: { type: 'simpleMarker' as const, color: '#16A34A', size: 14, style: 'circle' as const } },\n        ];\n      },\n    },\n  ];\n\n  async function run(op: (typeof OPS)[number]) {\n    try {\n      setGraphics(await op.run());\n    } catch (e) {\n      setStatus((e as { message?: string })?.message ?? String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ScrollView horizontal style={styles.barScroll} contentContainerStyle={styles.bar} showsHorizontalScrollIndicator={false}>\n        {OPS.map((op) => (\n          <Pressable key={op.key} style={styles.chip} onPress={() => run(op)}>\n            <Text style={styles.chipText}>{op.key}</Text>\n          </Pressable>\n        ))}\n      </ScrollView>\n      <Text style={styles.status}>{status}</Text>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ basemap: 'arcGISLightGray', initialViewpoint: { center: { latitude: 37, longitude: -100 }, scale: 30_000_000 }, graphics }}\n      />\n    </View>\n  );\n}\n","geoelementviewshed":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function GeoElementViewshedScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [{ id: 'buildings', url: brestBuildingsUrl }],\n        initialCamera: brestCamera,\n        analyses: [\n          {\n            type: 'geoElementViewshed',\n            location: { latitude: 48.4, longitude: -4.5, altitude: 100 },\n            headingDegrees: 20,\n            pitchDegrees: 70,\n            horizontalAngleDegrees: 45,\n            verticalAngleDegrees: 90,\n            minDistanceMeters: 50,\n            maxDistanceMeters: 1000,\n          },\n        ],\n      }}\n    />\n  );\n}\n","geoelementlineofsight":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function GeoElementLineOfSightScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [{ id: 'buildings', url: brestBuildingsUrl }],\n        initialCamera: brestCamera,\n        analyses: [\n          {\n            type: 'geoElementLineOfSight',\n            observer: { latitude: 48.3975, longitude: -4.505, altitude: 60 },\n            target: { latitude: 48.4, longitude: -4.5, altitude: 40 },\n          },\n        ],\n      }}\n    />\n  );\n}\n","distancemeasurement":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function DistanceMeasurementScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [{ id: 'buildings', url: brestBuildingsUrl }],\n        initialCamera: brestCamera,\n        analyses: [\n          {\n            type: 'distanceMeasurement',\n            startLocation: { latitude: 48.3975, longitude: -4.505, altitude: 20 },\n            endLocation: { latitude: 48.4, longitude: -4.5, altitude: 80 },\n            unitSystem: 'metric',\n          },\n        ],\n      }}\n    />\n  );\n}\n","cameraviewshed":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function CameraViewshedScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [{ id: 'buildings', url: brestBuildingsUrl }],\n        initialCamera: brestCamera,\n        analyses: [\n          {\n            type: 'cameraViewshed',\n            horizontalAngleDegrees: 90,\n            verticalAngleDegrees: 60,\n            minDistanceMeters: 20,\n            maxDistanceMeters: 1200,\n          },\n        ],\n      }}\n    />\n  );\n}\n","interactiveviewshed":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function InteractiveViewshedScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [{ id: 'buildings', url: brestBuildingsUrl }],\n        initialCamera: brestCamera,\n        analyses: [\n          {\n            type: 'interactiveViewshed',\n            location: { latitude: 48.4, longitude: -4.5, altitude: 100 },\n            headingDegrees: 20,\n            pitchDegrees: 70,\n            horizontalAngleDegrees: 90,\n            verticalAngleDegrees: 90,\n            minDistanceMeters: 20,\n            maxDistanceMeters: 1000,\n          },\n        ],\n      }}\n    />\n  );\n}\n","mapalgebra":"/**\n * `Apply function to raster from service` — applies a hillshade raster-function\n * chain to an image-service raster (the official sample's NLCD land-cover\n * service), producing shaded relief on the fly.\n */\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function MapAlgebraScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 43.7, longitude: -114.5 }, scale: 3_000_000 },\n          layers: [{ id: 'nlcd-algebra', type: 'raster', url: NLCD_URL, rasterFunction: MAP_ALGEBRA_FUNCTION }],\n        }}\n      />\n    </View>\n  );\n}\n","hotspots":"/**\n * Geoprocessing screens — analyze hotspots and calculate a viewshed — using the\n * job abstraction (`startGeoprocessingJob`) against the official Esri sample\n * geoprocessing services.\n */\nimport {\n  ArcgisMapView,\n  startGeoprocessingJob,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, View, Text } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official \"Analyze hotspots\" sample's 911-calls hotspot GP service + a\n// month-long date-range query (the exact service and query shape).\n\nexport function HotspotsScreen({ ready }: ScreenProps) {\n  const [mapImageUrl, setMapImageUrl] = useState<string | null>(null);\n  const [status, setStatus] = useState('Tap “Run analysis” to compute the hotspot map.');\n\n  async function run() {\n    setStatus('Running geoprocessing job…');\n    try {\n      const job = await startGeoprocessingJob({\n        serviceUrl: HOTSPOT_SERVICE,\n        inputs: [{ name: 'Query', type: 'string', value: HOTSPOT_QUERY }],\n      });\n      job.onProgress((e) => setStatus(`Job ${e.status} · ${Math.round(e.progress * 100)}%`));\n      const result = await job.result;\n      if (result.mapImageUrl) {\n        setMapImageUrl(result.mapImageUrl);\n        setStatus('Hotspot result map added.');\n      } else {\n        setStatus('Job finished but returned no result map image.');\n      }\n    } catch (error) {\n      setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISDarkGray',\n          initialViewpoint: { center: { latitude: 38.85, longitude: -77.03 }, scale: 1_100_000 },\n          layers: mapImageUrl ? [{ id: 'hotspot', type: 'mapImage', url: mapImageUrl }] : [],\n        }}\n      />\n      <View style={{ padding: 6 }}>\n        <Button title=\"Run analysis\" onPress={run} />\n      </View>\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","gpviewshed":"/**\n * Geoprocessing screens — analyze hotspots and calculate a viewshed — using the\n * job abstraction (`startGeoprocessingJob`) against the official Esri sample\n * geoprocessing services.\n */\nimport {\n  ArcgisMapView,\n  startGeoprocessingJob,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, View, Text } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official \"Analyze hotspots\" sample's 911-calls hotspot GP service + a\n// month-long date-range query (the exact service and query shape).\n\nexport function GeoprocessingViewshedScreen({ ready }: ScreenProps) {\n  const [graphics, setGraphics] = useState<GraphicSource[]>([]);\n  const [status, setStatus] = useState('Tap “Run viewshed” to compute the visible area.');\n\n  async function run() {\n    setStatus('Running viewshed job…');\n    try {\n      const job = await startGeoprocessingJob({\n        serviceUrl: VIEWSHED_SERVICE,\n        inputs: [\n          { name: 'Input_Observation_Point', type: 'point', point: VIEWSHED_OBSERVER },\n          { name: 'Viewshed_Distance', type: 'double', value: 5000 },\n        ],\n      });\n      job.onProgress((e) => setStatus(`Job ${e.status} · ${Math.round(e.progress * 100)}%`));\n      const result = await job.result;\n      setGraphics(\n        result.features.map((geometry, i) => ({\n          id: `viewshed-${i}`,\n          geometry,\n          symbol: {\n            type: 'simpleFill',\n            color: '#FFA50066',\n            outline: { type: 'simpleLine', color: '#FF8C00', width: 2 },\n          },\n        }))\n      );\n      setStatus(`Viewshed: ${result.features.length} polygon(s).`);\n    } catch (error) {\n      setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImagery',\n          initialViewpoint: { center: VIEWSHED_OBSERVER, scale: 120_000 },\n          graphics,\n        }}\n      />\n      <View style={{ padding: 6 }}>\n        <Button title=\"Run viewshed\" onPress={run} />\n      </View>\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","renderer":"import { ArcgisMapView, type ArcgisRenderer } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Esri's public US Census states layer (has SUB_REGION strings and POP2007\n// numbers) — used by Esri's own renderer samples.\n\nexport function RendererScreen({ ready }: ScreenProps) {\n  const [key, setKey] = useState('simple');\n  const active = RENDERERS.find((r) => r.key === key) ?? RENDERERS[0];\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        {RENDERERS.map((r) => (\n          <Pressable\n            key={r.key}\n            onPress={() => setKey(r.key)}\n            style={[styles.chip, key === r.key && styles.chipOn]}\n          >\n            <Text style={[styles.chipText, key === r.key && styles.chipTextOn]}>{r.label}</Text>\n          </Pressable>\n        ))}\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 70_000_000 },\n          featureLayers: [{ id: 'states', url: STATES_URL, renderer: active.renderer }],\n        }}\n      />\n    </View>\n  );\n}\n","labels":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function LabelsScreen({ ready }: ScreenProps) {\n  const [labelsOn, setLabelsOn] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={labelsOn ? 'Hide labels' : 'Show labels'}\n          onPress={() => setLabelsOn((on) => !on)}\n        />\n        <Text style={styles.status}>State abbreviations via `[STATE_ABBR]`.</Text>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 70_000_000 },\n          featureLayers: [\n            {\n              id: 'states',\n              url: STATES_URL,\n              labels: labelsOn\n                ? [\n                    {\n                      expression: '[STATE_ABBR]',\n                      color: '#1F2937',\n                      size: 12,\n                      haloColor: '#FFFFFF',\n                      haloWidth: 2,\n                    },\n                  ]\n                : [],\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","sceneorientation":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function SceneOrientationScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISTopographic',\n        elevationEnabled: true,\n        initialCamera: orientationCamera,\n        graphicsOverlays: [\n          {\n            id: 'oriented-cones',\n            surfacePlacement: 'absolute',\n            renderer: {\n              type: 'simple',\n              symbol: {\n                type: 'simpleMarkerScene',\n                style: 'cone',\n                color: '#FF3B30',\n                height: 200,\n                width: 80,\n                depth: 80,\n              },\n            },\n            // Each cone reads its own heading/pitch from these expressions.\n            orientationExpressions: {\n              headingExpression: '[HEADING]',\n              pitchExpression: '[PITCH]',\n            },\n            graphics: [0, 1, 2, 3, 4].map((i) => ({\n              id: `cone-${i}`,\n              geometry: {\n                type: 'point',\n                point: { latitude: 51.91, longitude: 4.39 + 0.006 * i, altitude: 300 },\n              },\n              // Per-graphic symbol satisfies validation; the overlay renderer\n              // (with its orientation expressions) is what actually draws them.\n              symbol: {\n                type: 'simpleMarkerScene',\n                style: 'cone',\n                color: '#FF3B30',\n                height: 200,\n                width: 80,\n                depth: 80,\n              },\n              attributes: { HEADING: i * 45, PITCH: i * 20 },\n            })),\n          },\n        ],\n      }}\n    />\n  );\n}\n","imageoverlay":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function ImageOverlayScreen({ ready }: ScreenProps) {\n  const { paths, status } = useProvisionedZipFrames(PACIFIC_SW_FRAMES_ITEM, 'pacific-sw-frames');\n  const [info, setInfo] = useState('Loading 3D scene…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!paths) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISOceans',\n          elevationEnabled: true,\n          initialCamera: pacificSwCamera,\n          imageOverlays: [\n            {\n              id: 'radar',\n              imagePaths: paths,\n              extent: pacificSwExtent,\n              framesPerSecond: 15,\n              opacity: 0.65,\n            },\n          ],\n        }}\n        onSceneLoad={() => setInfo(`Animating ${paths.length} frames.`)}\n        onSceneError={(e) => setInfo(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","cluster":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Toggles point clustering (feature reduction) on the Trailheads layer: nearby\n * points aggregate into sized bubbles; turning it off shows every point.\n */\n\nexport function ClusterScreen({ ready }: ScreenProps) {\n  const [clusterOn, setClusterOn] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={clusterOn ? 'Disable clustering' : 'Enable clustering'}\n          onPress={() => setClusterOn((on) => !on)}\n        />\n        <Text style={styles.status}>Zoom out to aggregate; zoom in to separate.</Text>\n      </View>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISNavigation',\n          initialViewpoint: { center: SANTA_MONICA, scale: 400_000 },\n          featureLayers: [\n            {\n              id: 'trailheads',\n              url: TRAILHEADS_URL,\n              clustering: { enabled: clusterOn, radius: 60, maxSymbolSize: 40, color: '#DB2777' },\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","customdictionary":"/**\n * Screens that style features/graphics from a local `.stylx` style file. The\n * style file is provisioned like the official ArcGIS samples app: downloaded\n * once from its ArcGIS Online portal item into the app cache, then passed to the\n * native view as a filesystem path.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function CustomDictionaryScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedFile(\n    '751138a2e0844e06853522d54103222a',\n    'Restaurant.stylx'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 34.0543, longitude: -117.1963 }, scale: 10000 },\n          featureLayers: [\n            {\n              id: 'restaurants',\n              url: 'https://services2.arcgis.com/ZQgQTuoyBrtmoGdP/arcgis/rest/services/Redlands_Restaurants/FeatureServer/0',\n              renderer: { type: 'dictionary', stylxPath: path },\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Map loaded.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","mobilestylesymbol":"/**\n * Screens that style features/graphics from a local `.stylx` style file. The\n * style file is provisioned like the official ArcGIS samples app: downloaded\n * once from its ArcGIS Online portal item into the app cache, then passed to the\n * native view as a filesystem path.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function MobileStyleSymbolScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedFile(\n    '1bd036f221f54a99abc9e46ff3511cbf',\n    'emoji-mobile.stylx'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImagery',\n          initialViewpoint: { center: { latitude: 34.05, longitude: -117.19 }, scale: 5000 },\n          graphics: [\n            {\n              id: 'emoji',\n              geometry: { type: 'point', point: { latitude: 34.05, longitude: -117.19 } },\n              // A cowboy-hatted, frowning emoji composed from the mobile style file.\n              symbol: {\n                type: 'webStyle',\n                symbolKey: 'Face1',\n                symbolKeys: ['Face1', 'Eyes-crossed', 'Hat-cowboy', 'Mouth-frown'],\n                stylxPath: path,\n              },\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Map loaded.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","rgbraster":"/**\n * Raster-renderer screens that apply a renderer to a *local* raster file, matching\n * the official \"Apply RGB renderer\" and \"Apply colormap renderer to raster\" samples.\n *\n * The official samples ship the Shasta GeoTIFFs in the app bundle. We provision the\n * exact same data the way the other local-data screens do: download the raster's\n * ArcGIS Online portal item (a `.zip`) once into the app cache, extract it — keeping\n * the GeoTIFF's sidecar files (`.tfw`, `.aux.xml`, `.ovr`) next to it — and hand the\n * native view the extracted file path.\n */\nimport { unzipSync } from 'fflate';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, type ArcgisLayerSource } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** ArcGIS-Online portal-item data endpoint for a public item. */\n\nexport function RgbRasterScreen(props: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedRaster(\n    '7c4c679ab06a4df19dc497f577f111bd',\n    'raster-rgb',\n    'raster-file/Shasta.tif'\n  );\n  const layer: ArcgisLayerSource | null = path\n    ? {\n        id: 'shasta-rgb',\n        type: 'raster',\n        path,\n        rgb: { bandIndices: [0, 1, 2], stretch: { type: 'percentClip', minPercent: 2, maxPercent: 2 } },\n      }\n    : null;\n  return <RasterScreen {...props} layer={layer} status={status} setStatus={setStatus} />;\n}\n","colormapraster":"/**\n * Raster-renderer screens that apply a renderer to a *local* raster file, matching\n * the official \"Apply RGB renderer\" and \"Apply colormap renderer to raster\" samples.\n *\n * The official samples ship the Shasta GeoTIFFs in the app bundle. We provision the\n * exact same data the way the other local-data screens do: download the raster's\n * ArcGIS Online portal item (a `.zip`) once into the app cache, extract it — keeping\n * the GeoTIFF's sidecar files (`.tfw`, `.aux.xml`, `.ovr`) next to it — and hand the\n * native view the extracted file path.\n */\nimport { unzipSync } from 'fflate';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, type ArcgisLayerSource } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** ArcGIS-Online portal-item data endpoint for a public item. */\n\nexport function ColormapRasterScreen(props: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedRaster(\n    'cc68728b5904403ba637e1f1cd2995ae',\n    'raster-colormap',\n    'ShastaBW.tif'\n  );\n  const layer: ArcgisLayerSource | null = path\n    ? { id: 'shasta-colormap', type: 'raster', path, colormap: { colors: rainbow(256) } }\n    : null;\n  return <RasterScreen {...props} layer={layer} status={status} setStatus={setStatus} />;\n}\n","blendraster":"/**\n * Raster-renderer screens that apply a renderer to a *local* raster file, matching\n * the official \"Apply RGB renderer\" and \"Apply colormap renderer to raster\" samples.\n *\n * The official samples ship the Shasta GeoTIFFs in the app bundle. We provision the\n * exact same data the way the other local-data screens do: download the raster's\n * ArcGIS Online portal item (a `.zip`) once into the app cache, extract it — keeping\n * the GeoTIFF's sidecar files (`.tfw`, `.aux.xml`, `.ovr`) next to it — and hand the\n * native view the extracted file path.\n */\nimport { unzipSync } from 'fflate';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, type ArcgisLayerSource } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** ArcGIS-Online portal-item data endpoint for a public item. */\n\nexport function BlendRasterScreen(props: ScreenProps) {\n  const color = useProvisionedRaster(\n    '7c4c679ab06a4df19dc497f577f111bd',\n    'raster-rgb',\n    'raster-file/Shasta.tif'\n  );\n  const elevation = useProvisionedRaster(\n    'cc68728b5904403ba637e1f1cd2995ae',\n    'raster-colormap',\n    'ShastaBW.tif'\n  );\n  const layer: ArcgisLayerSource | null =\n    color.path && elevation.path\n      ? {\n          id: 'shasta-blend',\n          type: 'raster',\n          path: color.path,\n          blend: {\n            elevationPath: elevation.path,\n            altitudeDegrees: 45,\n            azimuthDegrees: 315,\n            zFactor: 1,\n          },\n        }\n      : null;\n  return (\n    <RasterScreen\n      {...props}\n      layer={layer}\n      status={color.path ? elevation.status : color.status}\n      setStatus={elevation.setStatus}\n    />\n  );\n}\n","kmltour":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlTourScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [status, setStatus] = useState('Tap “Play” to start the KML tour.');\n\n  async function control(action: KmlTourAction) {\n    try {\n      await mapRef.current?.controlKmlTour({ layerId: TOUR_LAYER_ID, action });\n      setStatus(`Tour ${action === 'reset' ? 'reset' : `${action}ing`}.`);\n    } catch (error) {\n      setStatus(`${action} failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImagery',\n          initialViewpoint: { center: { latitude: 34.0, longitude: -117.2 }, scale: 20_000 },\n          layers: [{ id: TOUR_LAYER_ID, type: 'kml', url: TOUR_KML_URL }],\n        }}\n      />\n      <View style={styles.row}>\n        <Button title=\"Play\" onPress={() => control('play')} />\n        <Button title=\"Pause\" onPress={() => control('pause')} />\n        <Button title=\"Reset\" onPress={() => control('reset')} />\n      </View>\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","kmlgroundoverlay":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlGroundOverlayScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImagery',\n          initialViewpoint: { center: { latitude: 44.522, longitude: -85.982 }, scale: 250_000 },\n          layers: [\n            {\n              id: 'kml-ground-overlay',\n              type: 'kml',\n              url: GROUND_OVERLAY_KML_URL,\n              groundOverlayOpacity: 0.5,\n            },\n          ],\n        }}\n      />\n      <Text style={screenStyles.status}>KML ground overlay at 50% opacity.</Text>\n    </View>\n  );\n}\n","scenelayerrenderer":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function SceneLayerRendererScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISTopographic',\n        elevationEnabled: true,\n        initialCamera: helsinkiCamera,\n        sceneLayers: [\n          {\n            id: 'helsinki',\n            url: helsinkiSceneUrl,\n            // A single-symbol renderer recolours every building mesh.\n            renderer: { type: 'simple', symbol: { type: 'meshFill', color: '#FF8C00' } },\n          },\n        ],\n      }}\n    />\n  );\n}\n","scenerenderingmode":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function SceneRenderingModeScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISTopographic',\n        elevationEnabled: true,\n        initialCamera: geologyCamera,\n        featureLayers: [\n          { id: 'geology-polygon', url: `${geologyBase}/0`, renderingMode: 'dynamic' },\n          { id: 'geology-polyline', url: `${geologyBase}/8`, renderingMode: 'dynamic' },\n          { id: 'geology-point', url: `${geologyBase}/9`, renderingMode: 'dynamic' },\n        ],\n      }}\n    />\n  );\n}\n","shapefilesymbology":"/**\n * Screens that display a local shapefile, matching the official \"Apply symbology\n * to shapefile\" sample. The Aurora, CO shapefile ships in a `.zip` portal item,\n * provisioned via {@link useProvisionedZip}.\n */\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZip } from './provisioning';\n\n// The Subdivisions shapefile covers Aurora, Colorado (matching the official sample).\n\nexport function ShapefileSymbologyScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedZip(\n    'd98b3e5293834c5f852f13c569930caa',\n    'aurora-shp',\n    'Subdivisions.shp'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISStreets',\n          initialViewpoint: AURORA_VIEWPOINT,\n          layers: [\n            {\n              id: 'subdivisions',\n              type: 'shapefile',\n              path,\n              renderer: {\n                type: 'simple',\n                symbol: {\n                  type: 'simpleFill',\n                  style: 'solid',\n                  color: '#FFFF00',\n                  outline: { type: 'simpleLine', style: 'solid', color: '#FF0000', width: 1 },\n                },\n              },\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Shapefile loaded.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","shapefilemetadata":"/**\n * `Show shapefile metadata` — reads a local shapefile's descriptive metadata\n * (credits, description, summary, tags) via `getShapefileInfo`, without adding\n * it to a map. Uses the official sample's Aurora, CO shapefile, provisioned from\n * its portal-item `.zip`.\n */\nimport { getShapefileInfo, type ShapefileInfo } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZip } from './provisioning';\n\nexport function ShapefileMetadataScreen({ ready }: ScreenProps) {\n  const { path } = useProvisionedZip('d98b3e5293834c5f852f13c569930caa', 'aurora-shp', 'Subdivisions.shp');\n  const [info, setInfo] = useState<ShapefileInfo | null>(null);\n  const [status, setStatus] = useState('Preparing data…');\n\n  useEffect(() => {\n    if (!path) return;\n    setStatus('Reading metadata…');\n    getShapefileInfo(path)\n      .then((result) => {\n        setInfo(result);\n        setStatus('Metadata read.');\n      })\n      .catch((error: { code?: string }) => setStatus(`getShapefileInfo failed: ${error.code ?? 'error'}`));\n  }, [path]);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!info) {\n    return <Centered text={status} />;\n  }\n  const rows: [string, string][] = [\n    ['Summary', info.summary || '—'],\n    ['Description', info.description || '—'],\n    ['Credits', info.credits || '—'],\n    ['Copyright', info.copyrightText || '—'],\n    ['Tags', info.tags.length ? info.tags.join(', ') : '—'],\n  ];\n  return (\n    <View style={screenStyles.fill}>\n      <ScrollView contentContainerStyle={styles.content}>\n        {rows.map(([label, value]) => (\n          <View key={label} style={styles.row}>\n            <Text style={styles.label}>{label}</Text>\n            <Text style={styles.value}>{value}</Text>\n          </View>\n        ))}\n      </ScrollView>\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","sublayerclassbreaks":"/**\n * `Apply class breaks renderer to sublayer` — applies a class-breaks renderer to\n * one sublayer (Counties) of the Census dynamic map image service, colouring\n * counties by population (matches the official sample's data and field).\n */\nimport { ArcgisMapView, type ArcgisColor } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function SublayerClassBreaksScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -96 }, scale: 70_000_000 },\n          layers: [\n            {\n              id: 'census',\n              type: 'mapImage',\n              url: CENSUS_URL,\n              // Sublayer 2 is Counties; colour them by 2007 population.\n              sublayerRenderers: [\n                {\n                  sublayerId: 2,\n                  renderer: {\n                    type: 'classBreaks',\n                    field: 'POP2007',\n                    classBreaks: [\n                      { minValue: -99, maxValue: 8_560, symbol: fill('#FFFFB2'), label: '< 8.6k' },\n                      { minValue: 8_561, maxValue: 18_109, symbol: fill('#FECC5C'), label: '8.6k–18k' },\n                      { minValue: 18_110, maxValue: 35_501, symbol: fill('#FD8D3C'), label: '18k–36k' },\n                      { minValue: 35_502, maxValue: 86_100, symbol: fill('#F03B20'), label: '36k–86k' },\n                      { minValue: 86_101, maxValue: 10_110_975, symbol: fill('#BD0026'), label: '> 86k' },\n                    ],\n                  },\n                },\n              ],\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","rasterfunctionservice":"/**\n * `Apply function to raster from service` — applies a hillshade raster-function\n * chain to an image-service raster (the official sample's NLCD land-cover\n * service), producing shaded relief on the fly.\n */\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function RasterFunctionServiceScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 43.7, longitude: -114.5 }, scale: 3_000_000 },\n          layers: [{ id: 'nlcd-hillshade', type: 'raster', url: NLCD_URL, rasterFunction: HILLSHADE_FUNCTION }],\n        }}\n      />\n    </View>\n  );\n}\n","rasterrenderingrule":"/**\n * `Apply raster rendering rule` — requests a named server-side rendering rule\n * from an image service (the official sample's CharlotteLAS elevation service),\n * so the service returns a pre-processed image (here, a hillshade).\n */\nimport { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function RasterRenderingRuleScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 35.22, longitude: -80.84 }, scale: 40_000 },\n          // The service advertises RFTHillshade / RFTAspectColor / RFTShadedRelief…; request the hillshade.\n          layers: [{ id: 'charlotte-rule', type: 'raster', url: CHARLOTTE_LAS, renderingRule: 'RFTHillshade' }],\n        }}\n      />\n    </View>\n  );\n}\n","identify":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type SingleTapEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Taps the map, then `identify`s features/graphics at the tapped point. */\n\nexport function IdentifyScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [info, setInfo] = useState('Tap a trailhead to identify…');\n\n  async function onTap(event: SingleTapEventPayload) {\n    const { latitude, longitude } = event.mapPoint;\n    try {\n      const results =\n        (await mapRef.current?.identify({\n          screenPoint: event.screenPoint,\n          tolerance: 12,\n          maximumResults: 5,\n        })) ?? [];\n      if (results.length === 0) {\n        setInfo(`No features at ${latitude.toFixed(3)}, ${longitude.toFixed(3)}`);\n        return;\n      }\n      const first = results[0];\n      const name = first.attributes.TRL_NAME ?? first.attributes.name ?? JSON.stringify(first.attributes).slice(0, 48);\n      setInfo(`${results.length} result(s) · ${first.sourceId}: ${String(name)}`);\n    } catch {\n      setInfo('identify failed');\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 100_000 },\n          featureLayers: [{ id: 'trailheads', url: TRAILHEADS_URL }],\n          // A client-side marker at the center — identifiable without network.\n          graphics: [\n            {\n              id: 'pin',\n              geometry: { type: 'point', point: SANTA_MONICA },\n              symbol: { type: 'simpleMarker', color: '#d83933', size: 18 },\n            },\n          ],\n        }}\n        onSingleTap={({ nativeEvent }: { nativeEvent: SingleTapEventPayload }) => onTap(nativeEvent)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","arcadeexpression":"import {\n  ArcgisMapView,\n  type ArcadeEvaluationResult,\n  type ArcgisMapViewRef,\n  type SingleTapEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * `Query features with Arcade expression` — loads the official sample's Portland\n * \"RPD Beats\" web map, then evaluates an Arcade expression against the tapped\n * beat to count the crimes in the last 60 days that intersect it. The feature is\n * bound to `$feature` and the map (with its crime layer) to `$map`.\n */\n\nexport function ArcadeExpressionScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [result, setResult] = useState<ArcadeEvaluationResult | null>(null);\n  const [status, setStatus] = useState('Tap a police beat to count its recent crimes.');\n\n  async function onTap(event: SingleTapEventPayload) {\n    setStatus('Evaluating…');\n    setResult(null);\n    try {\n      const results =\n        (await mapRef.current?.evaluateArcade({\n          screenPoint: event.screenPoint,\n          expression: CRIMES_EXPRESSION,\n        })) ?? [];\n      if (results.length === 0) {\n        setStatus('No beat here — tap a police-beat polygon.');\n        return;\n      }\n      setResult(results[0]);\n      setStatus(`${results.length} beat(s) evaluated`);\n    } catch (error) {\n      setStatus(`evaluateArcade failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{ webMapItemId: CRIME_WEB_MAP_ITEM_ID, initialViewpoint: { center: PORTLAND, scale: 200_000 } }}\n        onSingleTap={({ nativeEvent }: { nativeEvent: SingleTapEventPayload }) => onTap(nativeEvent)}\n      />\n      {result ? (\n        <View style={styles.card}>\n          <Text style={styles.count}>{result.value}</Text>\n          <Text style={styles.caption}>crimes in the last 60 days in this beat</Text>\n        </View>\n      ) : (\n        <Text style={screenStyles.status}>{status}</Text>\n      )}\n    </View>\n  );\n}\n","popup":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type PopupInfo,\n  type SingleTapEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Loads a feature layer, then taps a feature to show its popup — title and\n * formatted fields — via `showPopup`. When the layer has no configured popup,\n * a default popup is generated from the feature's fields.\n */\n\nexport function PopupScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [popup, setPopup] = useState<PopupInfo | null>(null);\n  const [status, setStatus] = useState('Tap a feature to show its popup.');\n\n  async function onTap(event: SingleTapEventPayload) {\n    setStatus('Identifying…');\n    setPopup(null);\n    try {\n      const popups = (await mapRef.current?.showPopup({ screenPoint: event.screenPoint })) ?? [];\n      if (popups.length === 0) {\n        setStatus('No popup here — tap a feature.');\n        return;\n      }\n      setPopup(popups[0]);\n      setStatus(`${popups.length} popup(s)`);\n    } catch (error) {\n      setStatus(`showPopup failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 100_000 },\n          featureLayers: [{ id: 'trailheads', url: TRAILHEADS_URL }],\n        }}\n        onSingleTap={({ nativeEvent }: { nativeEvent: SingleTapEventPayload }) => onTap(nativeEvent)}\n      />\n      {popup ? (\n        <View style={styles.card}>\n          <Text style={styles.title}>{popup.title || 'Feature'}</Text>\n          <ScrollView style={styles.fieldList}>\n            {popup.fields.map((f, i) => (\n              <View key={`${f.label}-${i}`} style={styles.fieldRow}>\n                <Text style={styles.fieldLabel}>{f.label}</Text>\n                <Text style={styles.fieldValue}>{f.value}</Text>\n              </View>\n            ))}\n          </ScrollView>\n        </View>\n      ) : (\n        <Text style={screenStyles.status}>{status}</Text>\n      )}\n    </View>\n  );\n}\n","mapimagesublayer":"import {\n  queryMapImageSublayer,\n  type FeatureQueryResult,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, FlatList, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { USA_MAP_SERVICE_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The USA service's queryable sublayers and a demo where clause for each. */\n\nexport function MapImageSublayerScreen({ ready }: ScreenProps) {\n  const [rows, setRows] = useState<FeatureQueryResult[]>([]);\n  const [field, setField] = useState('STATE_NAME');\n  const [status, setStatus] = useState('Pick a sublayer to query.');\n\n  async function run(sub: (typeof SUBLAYERS)[number]) {\n    setStatus(`Querying ${sub.label}…`);\n    setRows([]);\n    setField(sub.field);\n    try {\n      const results = await queryMapImageSublayer(USA_MAP_SERVICE_URL, sub.id, sub.where);\n      setRows(results);\n      setStatus(`${results.length} feature(s) in sublayer ${sub.id}`);\n    } catch (error) {\n      setStatus(`query failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, styles.pad]}>\n      <View style={styles.buttons}>\n        {SUBLAYERS.map((sub) => (\n          <Button key={sub.id} title={sub.label} onPress={() => run(sub)} />\n        ))}\n      </View>\n      <Text style={styles.status}>{status}</Text>\n      <FlatList\n        data={rows}\n        keyExtractor={(_, i) => String(i)}\n        renderItem={({ item }) => (\n          <Text style={styles.row}>{String(item.attributes[field] ?? '—')}</Text>\n        )}\n      />\n    </View>\n  );\n}\n","query":"import { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Queries a feature layer by attribute expression via the ref's `queryFeatures`. */\n\nexport function QueryScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [info, setInfo] = useState('Tap a button to query the trailheads layer.');\n\n  async function runQuery(whereClause: string, label: string) {\n    try {\n      const results =\n        (await mapRef.current?.queryFeatures({\n          layerId: 'trailheads',\n          whereClause,\n          maxResults: 100,\n          select: true,\n        })) ?? [];\n      const first = results[0]?.attributes.TRL_NAME;\n      setInfo(`${label}: ${results.length} feature(s)${first ? ` · e.g. ${String(first)}` : ''}`);\n    } catch (error) {\n      setInfo(`query failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        <Button title=\"All\" onPress={() => runQuery('1=1', 'All')} />\n        <Button title=\"‘Canyon’\" onPress={() => runQuery(\"TRL_NAME LIKE '%Canyon%'\", 'Canyon')} />\n        <Button title=\"‘Park’\" onPress={() => runQuery(\"TRL_NAME LIKE '%Park%'\", 'Park')} />\n      </View>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 120_000 },\n          featureLayers: [{ id: 'trailheads', url: TRAILHEADS_URL }],\n        }}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","querydepth":"import { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function QueryDepthScreen({ ready }: ScreenProps) {\n  const ref = useRef<ArcgisMapViewRef>(null);\n  const [filtered, setFiltered] = useState(false);\n  const [status, setStatus] = useState('Filter, select, or count features.');\n\n  async function run(fn: () => Promise<string>) {\n    try {\n      setStatus(await fn());\n    } catch (e) {\n      setStatus(e instanceof Error ? e.message : String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={filtered ? 'Show all' : 'Pop > 5M'}\n          onPress={() => setFiltered((f) => !f)}\n        />\n        <Button\n          title=\"Select West\"\n          onPress={() =>\n            run(async () => {\n              const n = await ref.current!.selectFeatures({\n                layerId: 'states',\n                whereClause: \"SUB_REGION = 'Pacific' OR SUB_REGION = 'Mountain'\",\n              });\n              return `Selected ${n} western states`;\n            })\n          }\n        />\n        <Button\n          title=\"Count+extent\"\n          onPress={() =>\n            run(async () => {\n              const r = await ref.current!.queryFeatureExtent({\n                layerId: 'states',\n                whereClause: 'POP2007 > 5000000',\n              });\n              return r.extent\n                ? `${r.count} states >5M · extent ${r.extent.minLatitude.toFixed(0)},${r.extent.minLongitude.toFixed(0)}…`\n                : `${r.count} states`;\n            })\n          }\n        />\n      </View>\n      <Text style={styles.status}>{status}</Text>\n      <ArcgisMapView\n        ref={ref}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 70_000_000 },\n          featureLayers: [\n            {\n              id: 'states',\n              url: STATES_URL,\n              ...(filtered ? { definitionExpression: 'POP2007 > 5000000' } : {}),\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","querystats":"import { ArcgisMapView, type ArcgisMapViewRef, type StatisticsRow } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function QueryStatisticsScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [rows, setRows] = useState<StatisticsRow[]>([]);\n  const [status, setStatus] = useState('Tap “Compute” to aggregate by sub-region.');\n\n  async function compute() {\n    setStatus('Computing…');\n    try {\n      const result = await mapRef.current!.queryStatistics({\n        layerId: 'states',\n        statistics: [\n          { field: 'POP2007', type: 'sum', outName: 'total_pop' },\n          { field: 'POP2007', type: 'average', outName: 'avg_pop' },\n          { field: 'STATE_NAME', type: 'count', outName: 'states' },\n        ],\n        groupByFields: ['SUB_REGION'],\n      });\n      result.sort((a, b) => Number(b.statistics.total_pop) - Number(a.statistics.total_pop));\n      setRows(result);\n      setStatus(`${result.length} sub-regions (sorted by population)`);\n    } catch (e) {\n      setStatus((e as { message?: string })?.message ?? String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button title=\"Compute\" onPress={compute} />\n        <Text style={styles.status}>{status}</Text>\n      </View>\n      {rows.length > 0 && (\n        <ScrollView style={styles.table} contentContainerStyle={styles.tableInner}>\n          {rows.map((r) => (\n            <View key={String(r.group.SUB_REGION)} style={styles.row}>\n              <Text style={styles.region}>{String(r.group.SUB_REGION)}</Text>\n              <Text style={styles.stat}>\n                {Number(r.statistics.states)} states ·{' '}\n                {(Number(r.statistics.total_pop) / 1e6).toFixed(1)}M total\n              </Text>\n            </View>\n          ))}\n        </ScrollView>\n      )}\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 50_000_000 },\n          featureLayers: [{ id: 'states', url: STATES_URL, opacity: 0.6 }],\n        }}\n      />\n    </View>\n  );\n}\n","related":"import { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Esri's public Alaska national parks service; its parks relate to a species table.\n\nexport function RelatedFeaturesScreen({ ready }: ScreenProps) {\n  const ref = useRef<ArcgisMapViewRef>(null);\n  const [status, setStatus] = useState('Tap \"Related\" to query species for park #1.');\n  const [rows, setRows] = useState<string[]>([]);\n\n  async function queryRelated() {\n    try {\n      const results = await ref.current!.queryRelatedFeatures({ layerId: 'parks', objectId: 1 });\n      setRows(\n        results\n          .slice(0, 20)\n          .map((r) => String(r.attributes.Common_Name ?? r.attributes.Category ?? '—'))\n      );\n      setStatus(`${results.length} related species records`);\n    } catch (e) {\n      setStatus(e instanceof Error ? e.message : String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button title=\"Related species (park #1)\" onPress={queryRelated} />\n      </View>\n      <Text style={styles.status}>{status}</Text>\n      {rows.length > 0 && (\n        <ScrollView style={styles.list} contentContainerStyle={styles.listInner}>\n          {rows.map((r, i) => (\n            <Text key={i} style={styles.row}>\n              • {r}\n            </Text>\n          ))}\n        </ScrollView>\n      )}\n      <ArcgisMapView\n        ref={ref}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 63, longitude: -150 }, scale: 25_000_000 },\n          featureLayers: [{ id: 'parks', url: PARKS_URL }],\n        }}\n      />\n    </View>\n  );\n}\n","querydynamicentities":"/**\n * Dynamic-entity (real-time) screens — show a dynamic entity layer streaming\n * from a stream service, query its current entities, and replay a custom feed\n * from a local file.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisMapView, queryDynamicEntities } from 'expo-arcgis-maps-sdk';\nimport { useMemo, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// The official real-time samples' vehicle stream service.\n\nexport function QueryDynamicEntitiesScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Tap “Query” to snapshot current entities.');\n\n  async function run() {\n    setStatus('Querying stream service…');\n    try {\n      const result = await queryDynamicEntities({ url: STREAM_SERVICE });\n      const first = result.entities[0];\n      setStatus(\n        `${result.entities.length} entit${result.entities.length === 1 ? 'y' : 'ies'}` +\n          (first ? ` · first at ${first.latitude?.toFixed(3)}, ${first.longitude?.toFixed(3)}` : '')\n      );\n    } catch (error) {\n      setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, screenStyles.centered]}>\n      <Text style={screenStyles.status}>{status}</Text>\n      <View style={{ padding: 12 }}>\n        <Button title=\"Query\" onPress={run} />\n      </View>\n    </View>\n  );\n}\n","querytimeextent":"/**\n * `Query with time extent` — queries a time-aware feature service for the\n * features whose time falls within a window, via `queryFeaturesInTimeExtent`.\n * Mirrors the official sample: the Hurricanes service, September 2000.\n */\nimport { queryFeaturesInTimeExtent } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function QueryTimeExtentScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Tap “Query” for hurricanes in Sept 2000.');\n\n  async function run() {\n    setStatus('Querying time extent…');\n    try {\n      const features = await queryFeaturesInTimeExtent({\n        serviceUrl: HURRICANES,\n        startTime: START,\n        endTime: END,\n      });\n      setStatus(`${features.length} observation(s) in the time window.`);\n    } catch (error) {\n      setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, screenStyles.centered]}>\n      <Text style={screenStyles.status}>{status}</Text>\n      <View style={{ padding: 12 }}>\n        <Button title=\"Query\" onPress={run} />\n      </View>\n    </View>\n  );\n}\n","lineofsightmap":"/**\n * `Show line of sight analysis in map` — computes the line of sight between an\n * observer and a target against a local elevation raster (the official Monterey\n * DEM) via `computeLineOfSight`, then draws the visible (green) and obstructed\n * (red) portions as graphics on a 2D map.\n */\nimport { ArcgisMapView, computeLineOfSight, type GraphicSource } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZip } from './provisioning';\n\n// Two points over the Monterey terrain covered by the DEM.\n\nexport function LineOfSightMapScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedZip(\n    '98092369c4ae4d549bbbd45dba993ebc',\n    'monterey-elevation-raster',\n    'MontereyElevation.dt2'\n  );\n  const [graphics, setGraphics] = useState<GraphicSource[]>([]);\n\n  useEffect(() => {\n    if (!path) return;\n    let active = true;\n    (async () => {\n      try {\n        const result = await computeLineOfSight({\n          observer: OBSERVER,\n          target: TARGET,\n          elevationRasterPath: path,\n        });\n        if (!active) return;\n        const next: GraphicSource[] = [];\n        if (result.visibleLine) {\n          next.push({\n            id: 'visible',\n            geometry: result.visibleLine,\n            symbol: { type: 'simpleLine', color: '#2f9e44', width: 3 },\n          });\n        }\n        if (result.obstructedLine) {\n          next.push({\n            id: 'obstructed',\n            geometry: result.obstructedLine,\n            symbol: { type: 'simpleLine', style: 'dash', color: '#e03131', width: 3 },\n          });\n        }\n        setGraphics(next);\n        setStatus(`Target ${Math.round(result.targetVisibility * 100)}% visible.`);\n      } catch (error) {\n        if (active) setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n      }\n    })();\n    return () => {\n      active = false;\n    };\n  }, [path, setStatus]);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImagery',\n          initialViewpoint: { center: { latitude: 36.515, longitude: -121.8 }, scale: 40_000 },\n          graphics,\n        }}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","fcquery":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function FeatureCollectionQueryScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading feature collection from a query…');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISOceans',\n          initialViewpoint: { center: { latitude: 36.9, longitude: -120.5 }, scale: 12_000_000 },\n          layers: [\n            {\n              id: 'fc-query',\n              type: 'featureCollectionFromQuery',\n              url: 'https://sampleserver6.arcgisonline.com/arcgis/rest/services/Wildfire/FeatureServer/0',\n              where: '1=1',\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Feature collection built from a service query.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","subtypesublayer":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function SubtypeSublayerScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading subtype feature layer…');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISStreetsNight',\n          initialViewpoint: { center: { latitude: 41.8, longitude: -88.15 }, scale: 8_000 },\n          layers: [\n            {\n              id: 'subtype',\n              type: 'subtypeFeature',\n              url: 'https://sampleserver7.arcgisonline.com/server/rest/services/UtilityNetwork/NapervilleElectric/FeatureServer/0',\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Subtype feature layer loaded (sublayers by subtype).')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","wfsxmlquery":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function WfsXmlQueryScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading WFS layer with an XML query…');\n  const xmlQuery = `<?xml version=\"1.0\" encoding=\"utf-8\"?>\n<wfs:GetFeature service=\"WFS\" version=\"2.0.0\" xmlns:wfs=\"http://www.opengis.net/wfs/2.0\">\n  <wfs:Query typeNames=\"Seattle_Downtown_Features:Trees\"/>\n</wfs:GetFeature>`;\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISNavigation',\n          initialViewpoint: { center: { latitude: 47.605, longitude: -122.335 }, scale: 60_000 },\n          layers: [\n            {\n              id: 'wfs',\n              type: 'wfs',\n              url: 'https://dservices2.arcgis.com/ZQgQTuoyBrtmoGdP/arcgis/services/Seattle_Downtown_Features/WFSServer',\n              tableName: 'Seattle_Downtown_Features:Trees',\n              xmlQuery,\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('WFS layer populated by the XML query.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","featurerequestmode":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function FeatureRequestModeScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Feature layer using manual-cache request mode.');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 45.52, longitude: -122.68 }, scale: 30_000 },\n          featureLayers: [\n            {\n              id: 'trees',\n              url: 'https://services2.arcgis.com/ZQgQTuoyBrtmoGdP/arcgis/rest/services/Trees_of_Portland/FeatureServer/0',\n              featureRequestMode: 'manualCache',\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Feature request mode: manual cache.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","timeoffset":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function TimeOffsetScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Two hurricane layers, one offset by 10 days.');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  const url = 'https://sampleserver6.arcgisonline.com/arcgis/rest/services/Hurricanes/MapServer/0';\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISOceans',\n          initialViewpoint: { center: { latitude: 25, longitude: -60 }, scale: 60_000_000 },\n          featureLayers: [\n            { id: 'now', url },\n            { id: 'offset', url, timeOffset: { value: 10, unit: 'days' } },\n          ],\n        }}\n        onMapLoad={() => setStatus('Feature layer displayed with a 10-day time offset.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","featurerenderingmodemap":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function FeatureRenderingModeMapScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Feature layer with static rendering mode.');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 39, longitude: -101 }, scale: 40_000_000 },\n          featureLayers: [\n            {\n              id: 'geology',\n              url: 'https://sampleserver6.arcgisonline.com/arcgis/rest/services/Energy/Geology/FeatureServer/8',\n              renderingMode: 'static',\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('Feature layer rendering mode set on the map.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","pointscenelayer":"/**\n * Demo screens for shipped capabilities that previously had no example screen —\n * layer types and feature-layer properties. Each mirrors the official sample's\n * data.\n */\nimport { ArcgisMapView, ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Add feature collection layer from query` — features copied from a service query. */\n\nexport function PointSceneLayerScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading point scene layer…');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: POINT_SCENE_CAMERA,\n          sceneLayers: [\n            {\n              id: 'airports',\n              type: 'scene',\n              url: 'https://tiles.arcgis.com/tiles/V6ZHFr6zdgNZuVG0/arcgis/rest/services/Airports_PointSceneLayer/SceneServer/layers/0',\n            },\n          ],\n        }}\n        onSceneLoad={() => setStatus('Point scene layer loaded.')}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","geodesicsectorellipse":"/**\n * Demo screens for shipped capabilities that had no example screen — geometry\n * ops, graphics renderers, operational-layer management, and a styled WMS layer.\n */\nimport {\n  ArcgisMapView,\n  geodesicEllipse,\n  geodesicSector,\n  type ArcgisLayerSource,\n  type ArcgisMapViewRef,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function GeodesicSectorEllipseScreen({ ready }: ScreenProps) {\n  const [graphics, setGraphics] = useState<GraphicSource[]>([]);\n  const [status, setStatus] = useState('Computing geodesic ellipse and sector…');\n\n  useEffect(() => {\n    let active = true;\n    (async () => {\n      try {\n        const ellipse = await geodesicEllipse({\n          center: CENTER,\n          semiAxis1LengthMeters: 30_000,\n          semiAxis2LengthMeters: 15_000,\n          axisDirectionDegrees: 45,\n        });\n        const sector = await geodesicSector({\n          center: CENTER,\n          semiAxis1LengthMeters: 25_000,\n          semiAxis2LengthMeters: 25_000,\n          sectorAngleDegrees: 70,\n          startDirectionDegrees: 10,\n        });\n        if (!active) return;\n        setGraphics([\n          {\n            id: 'ellipse',\n            geometry: ellipse,\n            symbol: { type: 'simpleFill', color: '#2f7d6e40', outline: { type: 'simpleLine', color: '#2f7d6e', width: 2 } },\n          },\n          {\n            id: 'sector',\n            geometry: sector,\n            symbol: { type: 'simpleFill', color: '#e4572e55', outline: { type: 'simpleLine', color: '#e4572e', width: 2 } },\n          },\n        ]);\n        setStatus('Geodesic ellipse (green) and sector (orange).');\n      } catch (error) {\n        if (active) setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n      }\n    })();\n    return () => {\n      active = false;\n    };\n  }, []);\n\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: CENTER, scale: 800_000 },\n          graphics,\n        }}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","manageoperationallayers":"/**\n * Demo screens for shipped capabilities that had no example screen — geometry\n * ops, graphics renderers, operational-layer management, and a styled WMS layer.\n */\nimport {\n  ArcgisMapView,\n  geodesicEllipse,\n  geodesicSector,\n  type ArcgisLayerSource,\n  type ArcgisMapViewRef,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ManageOperationalLayersScreen({ ready }: ScreenProps) {\n  const censusLayer: ArcgisLayerSource = {\n    id: 'census',\n    type: 'mapImage',\n    url: 'https://sampleserver5.arcgisonline.com/arcgis/rest/services/Census/MapServer',\n  };\n  const damageLayer: ArcgisLayerSource = {\n    id: 'damage',\n    type: 'mapImage',\n    url: 'https://sampleserver5.arcgisonline.com/arcgis/rest/services/DamageAssessment/MapServer',\n  };\n  const [layers, setLayers] = useState<ArcgisLayerSource[]>([censusLayer, damageLayer]);\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 39, longitude: -96 }, scale: 90_000_000 },\n          // Reordering the declarative array reorders the operational layers.\n          layers,\n        }}\n      />\n      <View style={styles.bar}>\n        <Pressable style={styles.btn} onPress={() => setLayers((l) => [...l].reverse())}>\n          <Text style={styles.btnText}>Swap order</Text>\n        </Pressable>\n        <Pressable style={styles.btn} onPress={() => setLayers([censusLayer, damageLayer])}>\n          <Text style={styles.btnText}>Reset</Text>\n        </Pressable>\n        <Text style={styles.status}>Top layer: {layers[layers.length - 1]?.id}</Text>\n      </View>\n    </View>\n  );\n}\n","wmsstyle":"/**\n * Demo screens for shipped capabilities that had no example screen — geometry\n * ops, graphics renderers, operational-layer management, and a styled WMS layer.\n */\nimport {\n  ArcgisMapView,\n  geodesicEllipse,\n  geodesicSector,\n  type ArcgisLayerSource,\n  type ArcgisMapViewRef,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function WmsStyleScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading WMS layer with a style…');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 46.3, longitude: -94.3 }, scale: 12_000_000 },\n          layers: [\n            {\n              id: 'wms',\n              type: 'wms',\n              url: 'https://imageserver.gisdata.mn.gov/cgi-bin/mncomp?SERVICE=WMS&VERSION=1.3.0&REQUEST=GetCapabilities',\n              layerNames: ['mncomp'],\n              styleName: 'default',\n            },\n          ],\n        }}\n        onMapLoad={() => setStatus('WMS layer displayed with a named style.')}\n        onMapError={(e) => setStatus(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","stylegraphicsrenderer":"/**\n * Demo screens for shipped capabilities that had no example screen — geometry\n * ops, graphics renderers, operational-layer management, and a styled WMS layer.\n */\nimport {\n  ArcgisMapView,\n  geodesicEllipse,\n  geodesicSector,\n  type ArcgisLayerSource,\n  type ArcgisMapViewRef,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function StyleGraphicsWithRendererScreen({ ready }: ScreenProps) {\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  // The graphics carry no symbol; the overlay's shared renderer styles them all.\n  const points: GraphicSource[] = [\n    { latitude: 34.05, longitude: -118.8 },\n    { latitude: 34.02, longitude: -118.77 },\n    { latitude: 34.0, longitude: -118.83 },\n    { latitude: 34.04, longitude: -118.86 },\n  ].map((point, i) => ({ id: `p${i}`, geometry: { type: 'point', point } }));\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: CENTER, scale: 400_000 },\n          graphicsRenderer: {\n            type: 'simple',\n            symbol: { type: 'simpleMarker', style: 'diamond', color: '#8a3ffc', size: 16 },\n          },\n          graphics: points,\n        }}\n      />\n      <Text style={screenStyles.status}>One renderer styles every (symbol-less) overlay graphic.</Text>\n    </View>\n  );\n}\n","identifywms":"/**\n * Demo screens for shipped capabilities that had no example screen — geometry\n * ops, graphics renderers, operational-layer management, and a styled WMS layer.\n */\nimport {\n  ArcgisMapView,\n  geodesicEllipse,\n  geodesicSector,\n  type ArcgisLayerSource,\n  type ArcgisMapViewRef,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function IdentifyWmsScreen({ ready }: ScreenProps) {\n  const ref = useRef<ArcgisMapViewRef>(null);\n  const [status, setStatus] = useState('Tap the map to identify WMS features.');\n  if (!ready) return <Centered text=\"Waiting for configuration…\" />;\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={ref}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39, longitude: -98 }, scale: 40_000_000 },\n          layers: [\n            {\n              id: 'wms',\n              type: 'wms',\n              url: 'https://watersgeo.epa.gov/arcgis/services/OWPROGRAM/SDWIS_WMERC/MapServer/WMSServer?request=GetCapabilities&service=WMS',\n              layerNames: ['4'],\n            },\n          ],\n        }}\n        onSingleTap={async (e) => {\n          try {\n            const results = await ref.current?.identify({ screenPoint: e.nativeEvent.screenPoint });\n            const wms = (results ?? []).filter((r) => r.sourceId === 'wms');\n            setStatus(`${wms.length} WMS feature(s) at the tapped point.`);\n          } catch (error) {\n            setStatus(`identify failed: ${(error as { code?: string }).code ?? 'error'}`);\n          }\n        }}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","ogccql":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Esri's public OGC API - Features demo service (Daraa, Syria).\n\nexport function OgcCqlScreen({ ready }: ScreenProps) {\n  const [cql, setCql] = useState(true);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.bar}>\n        <Button\n          title={cql ? 'Clear CQL filter' : \"Filter F_CODE = 'AP030'\"}\n          onPress={() => setCql((on) => !on)}\n        />\n        <Text style={styles.status}>{cql ? 'Roads only (CQL2)' : 'All transport features'}</Text>\n      </View>\n      <ArcgisMapView\n        // Remount so the collection repopulates with/without the CQL filter.\n        key={cql ? 'cql' : 'all'}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: { latitude: 32.62, longitude: 36.1 }, scale: 30_000 },\n          layers: [\n            {\n              id: 'ogc',\n              type: 'ogcFeature',\n              url: OGC_URL,\n              collectionId: 'TransportationGroundCrv',\n              ...(cql ? { cqlFilter: \"F_CODE = 'AP030'\" } : {}),\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","geocode":"import { geocode, reverseGeocode } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, TextInput, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { LONDON, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Forward + reverse geocoding via the module's `geocode` / `reverseGeocode`. */\n\nexport function GeocodeScreen({ ready }: ScreenProps) {\n  const [address, setAddress] = useState('Redlands, CA');\n  const [result, setResult] = useState('Enter an address and tap Search.');\n\n  async function search() {\n    setResult('Searching…');\n    try {\n      const results = await geocode(address);\n      if (results.length === 0) {\n        setResult('No matches.');\n        return;\n      }\n      const r = results[0];\n      const score = r.score != null ? ` (score ${Math.round(r.score)})` : '';\n      setResult(\n        `${r.label}\\n${r.location.latitude.toFixed(4)}, ${r.location.longitude.toFixed(4)}${score}`\n      );\n    } catch (error) {\n      setResult(`geocode failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function reverse() {\n    setResult('Reverse geocoding London…');\n    try {\n      const results = await reverseGeocode(LONDON);\n      setResult(results.length ? `Reverse London →\\n${results[0].label}` : 'No address found.');\n    } catch (error) {\n      setResult(`reverse failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, styles.pad]}>\n      <TextInput\n        style={styles.input}\n        value={address}\n        onChangeText={setAddress}\n        placeholder=\"Address or place\"\n        autoCapitalize=\"words\"\n      />\n      <View style={styles.row}>\n        <Button title=\"Search\" onPress={search} />\n        <Button title=\"Reverse London\" onPress={reverse} />\n      </View>\n      <Text style={styles.result}>{result}</Text>\n    </View>\n  );\n}\n","routedisplay":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function DisplayRouteLayerScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const r = await solveRoute([STOP_A, STOP_B]);\n        return { status: `Route layer drawn (${(r.distanceMeters / 1000).toFixed(1)} km)`, graphics: [...stops, line('route', r.path)] };\n      }}\n    />\n  );\n}\n","closestfacility":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FindClosestFacilityScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const r = await findClosestFacility({ incident: STOP_A, facilities: FACILITIES });\n        return {\n          status: `Closest: #${r.facilityIndex} · ${(r.distanceMeters / 1000).toFixed(1)} km`,\n          graphics: [\n            marker('incident', STOP_A, stopMarker),\n            ...FACILITIES.map((f, i) => marker(`fac-${i}`, f, facilityMarker)),\n            line('route', r.path),\n          ],\n        };\n      }}\n    />\n  );\n}\n","closestfacilitymulti":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FindClosestFacilityMultiScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const incidents = [STOP_A, STOP_B];\n        const routes = await findClosestFacilities(incidents, FACILITIES);\n        return {\n          status: `${routes.length} incident(s) routed to nearest facility`,\n          graphics: [\n            ...incidents.map((p, i) => marker(`inc-${i}`, p, stopMarker)),\n            ...FACILITIES.map((f, i) => marker(`fac-${i}`, f, facilityMarker)),\n            ...routes.map((r) => line(`route-${r.incidentIndex}`, r.path)),\n          ],\n        };\n      }}\n    />\n  );\n}\n","route":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FindRouteScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const r = await solveRoute([STOP_A, STOP_B]);\n        return { status: `Route: ${(r.distanceMeters / 1000).toFixed(1)} km`, graphics: [...stops, line('route', r.path)] };\n      }}\n    />\n  );\n}\n","routebarriers":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FindRouteBarriersScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const r = await solveRoute([STOP_A, STOP_B], { polygonBarriers: [BARRIER] });\n        return {\n          status: `Detour: ${(r.distanceMeters / 1000).toFixed(1)} km`,\n          graphics: [...stops, { id: 'barrier', geometry: BARRIER, symbol: barrierFill }, line('route', r.path)],\n        };\n      }}\n    />\n  );\n}\n","routenetwork":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FindRouteNetworkScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const r = await solveRouteInNetwork('san_diego.geodatabase', 'Streets_ND', [STOP_A, STOP_B]);\n        return { status: `Network route: ${(r.distanceMeters / 1000).toFixed(1)} km`, graphics: [...stops, line('route', r.path)] };\n      }}\n    />\n  );\n}\n","navigate":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type GeographicPoint,\n  type NavigationStatusEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, View, Text } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function NavigateRouteScreen(props: ScreenProps) {\n  return <NavigationDemo {...props} reroute={false} />;\n}\n","navigatereroute":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type GeographicPoint,\n  type NavigationStatusEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, View, Text } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function NavigateRerouteScreen(props: ScreenProps) {\n  return <NavigationDemo {...props} reroute />;\n}\n","servicearea":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ShowServiceAreaScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const r = await findServiceArea({ facility: STOP_A, breaksMinutes: [3, 5, 8] });\n        return {\n          status: `${r.polygons.length} drive-time areas (3/5/8 min)`,\n          graphics: [\n            ...r.polygons.map((geometry, i) => areaFill(`area-${i}`, geometry, i)),\n            marker('facility', STOP_A, stopMarker),\n          ],\n        };\n      }}\n    />\n  );\n}\n","serviceareamulti":"/**\n * Routing & Logistics example screens, one per official ArcGIS sample so each\n * shipped capability has its own demo screen (mirrors the Esri samples app).\n */\nimport {\n  ArcgisMapView,\n  findClosestFacilities,\n  findClosestFacility,\n  findServiceArea,\n  findServiceAreas,\n  solveRoute,\n  solveRouteInNetwork,\n  type ArcgisGeometry,\n  type ArcgisSymbol,\n  type GeographicPoint,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ShowServiceAreasMultiScreen(props: ScreenProps) {\n  return (\n    <RoutingDemo\n      {...props}\n      run={async () => {\n        const areas = await findServiceAreas(FACILITIES, [5, 10]);\n        const total = areas.reduce((n, a) => n + a.polygons.length, 0);\n        return {\n          status: `${total} areas around ${areas.length} facilities (5/10 min)`,\n          graphics: [\n            ...areas.flatMap((a) => a.polygons.map((geometry, i) => areaFill(`sa-${a.facilityIndex}-${i}`, geometry, i))),\n            ...FACILITIES.map((f, i) => marker(`fac-${i}`, f, facilityMarker)),\n          ],\n        };\n      }}\n    />\n  );\n}\n","transformations":"import {\n  getTransformations,\n  projectPoint,\n  type GeographicPoint,\n  type TransformationInfo,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Pressable, ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\n\n// Royal Observatory, Greenwich — projecting WGS 84 → British National Grid\n// (EPSG:27700) has several datum transformations whose results differ by metres.\n\nexport function TransformationsScreen({ ready }: ScreenProps) {\n  const [transforms, setTransforms] = useState<TransformationInfo[]>([]);\n  const [selected, setSelected] = useState<string | null>(null);\n  const [projected, setProjected] = useState<string>('');\n  const [status, setStatus] = useState('Loading transformations…');\n\n  useEffect(() => {\n    if (!ready) return;\n    getTransformations(4326, BNG_WKID)\n      .then((list) => {\n        setTransforms(list);\n        setStatus(`${list.length} transformations (WGS 84 → British National Grid)`);\n      })\n      .catch((e) => setStatus((e as { message?: string })?.message ?? String(e)));\n  }, [ready]);\n\n  async function pick(t: TransformationInfo) {\n    setSelected(t.name);\n    try {\n      const p = await projectPoint(POINT, BNG_WKID, t.name);\n      setProjected(`E ${p.x.toFixed(1)}  N ${p.y.toFixed(1)}`);\n    } catch (e) {\n      setProjected((e as { message?: string })?.message ?? String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.fill}>\n      <Text style={styles.status}>{status}</Text>\n      <Text style={styles.coords}>\n        {projected ? `Greenwich → ${projected}` : 'Tap a transformation to project the point.'}\n      </Text>\n      <ScrollView contentContainerStyle={styles.list}>\n        {transforms.map((t) => (\n          <Pressable\n            key={t.name}\n            style={[styles.row, selected === t.name && styles.rowActive]}\n            onPress={() => pick(t)}\n          >\n            <Text style={[styles.name, selected === t.name && styles.nameActive]} numberOfLines={2}>\n              {t.name}\n            </Text>\n            {t.isMissingProjectionEngineFiles && <Text style={styles.warn}>needs PE files</Text>}\n          </Pressable>\n        ))}\n      </ScrollView>\n    </View>\n  );\n}\n","kmlcontents":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlContentsScreen({ ready }: ScreenProps) {\n  const [nodes, setNodes] = useState<KmlNodeInfo[] | null>(null);\n  const [status, setStatus] = useState('Reading KML contents…');\n  useEffect(() => {\n    let cancelled = false;\n    (async () => {\n      try {\n        const info = await getKmlInfo({ url: NETWORK_LINK_KML });\n        if (!cancelled) {\n          setNodes(info.nodes);\n          setStatus(`${info.nodes.length} node(s).`);\n        }\n      } catch (error) {\n        if (!cancelled) setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n      }\n    })();\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, { padding: 16 }]}>\n      <Text style={screenStyles.status}>{status}</Text>\n      {(nodes ?? []).slice(0, 40).map((node, i) => (\n        <Text key={i} style={{ paddingLeft: 12 * node.depth }}>\n          {node.type === 'folder' || node.type === 'document' ? '📁' : '•'} {node.name || '(unnamed)'}{' '}\n          <Text style={{ color: '#888' }}>[{node.type}]</Text>\n        </Text>\n      ))}\n    </View>\n  );\n}\n","kmlsave":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlSaveScreen({ ready }: ScreenProps) {\n  const [path, setPath] = useState<string | null>(null);\n  const [status, setStatus] = useState('Authoring KML…');\n  useEffect(() => {\n    let cancelled = false;\n    (async () => {\n      try {\n        const result = await createKmlFile({\n          path: authoredKmlPath('places.kmz'),\n          placemarks: [\n            { name: 'Los Angeles', point: { latitude: 34.05, longitude: -118.24 } },\n            { name: 'Denver', point: { latitude: 39.74, longitude: -104.99 } },\n            { name: 'New York', point: { latitude: 40.71, longitude: -74.01 } },\n          ],\n        });\n        if (!cancelled) {\n          setPath(result.path);\n          setStatus('Authored 3 placemarks; displaying the saved KML.');\n        }\n      } catch (error) {\n        if (!cancelled) setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n      }\n    })();\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      {path ? (\n        <ArcgisMapView\n          style={screenStyles.fill}\n          map={{\n            basemap: 'arcGISLightGray',\n            initialViewpoint: { center: { latitude: 39, longitude: -96 }, scale: 40_000_000 },\n            layers: [{ id: 'authored-kml', type: 'kml', url: path }],\n          }}\n        />\n      ) : (\n        <Centered text={status} />\n      )}\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","kmlmultitrack":"/**\n * KML depth screens — tour playback, ground-overlay opacity, network links,\n * feature identify, listing contents, and authoring KML (save + multi-track) —\n * mirroring the official KML samples.\n */\nimport {\n  ArcgisMapView,\n  createKmlFile,\n  getKmlInfo,\n  type ArcgisMapViewRef,\n  type KmlNodeInfo,\n  type KmlTourAction,\n} from 'expo-arcgis-maps-sdk';\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { useEffect, useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** The native SDKs expect a plain filesystem path, not a `file://` URI. */\n\nexport function KmlMultiTrackScreen({ ready }: ScreenProps) {\n  const [path, setPath] = useState<string | null>(null);\n  const [status, setStatus] = useState('Authoring KML multi-track…');\n  useEffect(() => {\n    let cancelled = false;\n    (async () => {\n      try {\n        const result = await createKmlFile({\n          path: authoredKmlPath('track.kmz'),\n          tracks: [\n            {\n              points: [\n                { latitude: 34.05, longitude: -118.24 },\n                { latitude: 36.11, longitude: -115.17 },\n                { latitude: 39.74, longitude: -104.99 },\n                { latitude: 41.88, longitude: -87.63 },\n              ],\n            },\n          ],\n        });\n        if (!cancelled) {\n          setPath(result.path);\n          setStatus('Authored a multi-track; displaying the saved KML.');\n        }\n      } catch (error) {\n        if (!cancelled) setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n      }\n    })();\n    return () => {\n      cancelled = true;\n    };\n  }, []);\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      {path ? (\n        <ArcgisMapView\n          style={screenStyles.fill}\n          map={{\n            basemap: 'arcGISLightGray',\n            initialViewpoint: { center: { latitude: 38, longitude: -103 }, scale: 30_000_000 },\n            layers: [{ id: 'authored-track', type: 'kml', url: path }],\n          }}\n        />\n      ) : (\n        <Centered text={status} />\n      )}\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","reticleeditor":"/**\n * Edit-depth screens — the reticle geometry-editor tool, branch versioning, and\n * feature-linked annotation editing.\n */\nimport {\n  ArcgisMapView,\n  createServiceVersion,\n  getServiceVersions,\n  type ArcgisMapViewRef,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Edit geometries with programmatic reticle tool` — drop vertices under a fixed reticle. */\n\nexport function ReticleEditorScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [editing, setEditing] = useState(false);\n  const [status, setStatus] = useState('Start the reticle editor, then tap to drop vertices.');\n\n  async function start() {\n    try {\n      await mapRef.current?.startGeometryEditor({ geometryType: 'polygon', tool: 'reticle' });\n      setEditing(true);\n      setStatus('Move the map so the reticle is over a point, then tap to place it.');\n    } catch (error) {\n      setStatus(`start failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n  async function finish() {\n    try {\n      const geometry = await mapRef.current?.stopGeometryEditor();\n      setEditing(false);\n      setStatus(geometry ? 'Captured a polygon with the reticle tool.' : 'Nothing was drawn.');\n    } catch (error) {\n      setStatus(`stop failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISImagery',\n          initialViewpoint: { center: { latitude: 34.056, longitude: -117.19 }, scale: 5_000 },\n        }}\n      />\n      <View style={styles.row}>\n        {editing ? (\n          <Button title=\"Finish\" onPress={finish} />\n        ) : (\n          <Button title=\"Start reticle editor\" onPress={start} />\n        )}\n      </View>\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","branchversion":"/**\n * Edit-depth screens — the reticle geometry-editor tool, branch versioning, and\n * feature-linked annotation editing.\n */\nimport {\n  ArcgisMapView,\n  createServiceVersion,\n  getServiceVersions,\n  type ArcgisMapViewRef,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Edit geometries with programmatic reticle tool` — drop vertices under a fixed reticle. */\n\nexport function BranchVersionScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Tap “Create version” (needs a signed-in named user).');\n\n  async function run() {\n    setStatus('Creating branch version…');\n    try {\n      const result = await createServiceVersion({\n        serviceUrl: BRANCH_SERVICE,\n        versionName: `edits_${Date.now()}`,\n        description: 'Created from the example app',\n        access: 'private',\n      });\n      setStatus(`Switched to version \"${result.versionName}\".`);\n    } catch (error) {\n      setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, screenStyles.centered]}>\n      <Text style={screenStyles.status}>{status}</Text>\n      <View style={{ padding: 12 }}>\n        <Button title=\"Create version\" onPress={run} />\n      </View>\n    </View>\n  );\n}\n","listversions":"/**\n * Edit-depth screens — the reticle geometry-editor tool, branch versioning, and\n * feature-linked annotation editing.\n */\nimport {\n  ArcgisMapView,\n  createServiceVersion,\n  getServiceVersions,\n  type ArcgisMapViewRef,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Edit geometries with programmatic reticle tool` — drop vertices under a fixed reticle. */\n\nexport function ListVersionsScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Tap “List versions” (needs a signed-in named user).');\n\n  async function run() {\n    setStatus('Fetching versions…');\n    try {\n      const versions = await getServiceVersions(BRANCH_SERVICE);\n      setStatus(\n        versions.length === 0\n          ? 'No versions returned.'\n          : versions.map((v) => `${v.name} (${v.access})`).join('\\n')\n      );\n    } catch (error) {\n      setStatus(`Failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, screenStyles.centered]}>\n      <Text style={screenStyles.status}>{status}</Text>\n      <View style={{ padding: 12 }}>\n        <Button title=\"List versions\" onPress={run} />\n      </View>\n    </View>\n  );\n}\n","featurelinkedannotation":"/**\n * Edit-depth screens — the reticle geometry-editor tool, branch versioning, and\n * feature-linked annotation editing.\n */\nimport {\n  ArcgisMapView,\n  createServiceVersion,\n  getServiceVersions,\n  type ArcgisMapViewRef,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Edit geometries with programmatic reticle tool` — drop vertices under a fixed reticle. */\n\nexport function FeatureLinkedAnnotationScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading features + linked annotation…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISLightGray',\n          initialViewpoint: { center: { latitude: 39.083, longitude: -77.65 }, scale: 2_000 },\n          layers: [\n            { id: 'addresses', type: 'annotation', url: FEATURE_LINKED_ANNOTATION_LAYER },\n          ],\n          featureLayers: [{ id: 'points', url: FEATURE_LINKED_ANNOTATION }],\n        }}\n        onMapLoad={() => setInfo('Editing a feature moves its linked annotation with it.')}\n        onMapError={(e) => setInfo(`map error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","creategdb":"import { createMobileGeodatabase, type MobileGeodatabaseResult } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\n\n/**\n * Create a mobile geodatabase (\"Create mobile geodatabase\"): builds a new local\n * `.geodatabase` file with a point feature table (name / date fields), adds a\n * few sample features, and reports the file path and feature count. Fully local\n * — no network or API key needed.\n */\n\nexport function CreateGeodatabaseScreen({ ready }: ScreenProps) {\n  const [result, setResult] = useState<MobileGeodatabaseResult | null>(null);\n  const [status, setStatus] = useState('Tap “Create” to build a mobile geodatabase.');\n\n  async function create() {\n    setStatus('Creating…');\n    setResult(null);\n    try {\n      const r = await createMobileGeodatabase({\n        tableName: 'LocationHistory',\n        geometryType: 'point',\n        fields: [\n          { name: 'name', type: 'text' },\n          { name: 'collected', type: 'date' },\n          { name: 'count', type: 'integer' },\n        ],\n      });\n      setResult(r);\n      setStatus(`Created “${r.tableName}” with ${r.featureCount} features.`);\n    } catch (e) {\n      setStatus((e as { message?: string })?.message ?? String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.fill}>\n      <View style={styles.bar}>\n        <Button title=\"Create\" onPress={create} />\n      </View>\n      <Text style={styles.status}>{status}</Text>\n      {result && (\n        <View style={styles.card}>\n          <Text style={styles.label}>Table</Text>\n          <Text style={styles.value}>{result.tableName}</Text>\n          <Text style={styles.label}>Features</Text>\n          <Text style={styles.value}>{result.featureCount}</Text>\n          <Text style={styles.label}>File</Text>\n          <Text style={styles.path} numberOfLines={3}>\n            {result.path}\n          </Text>\n        </View>\n      )}\n    </View>\n  );\n}\n","gdbtransaction":"import { applyGeodatabaseTransaction, createMobileGeodatabase } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\n\nexport function GeodatabaseTransactionScreen({ ready }: ScreenProps) {\n  const [path, setPath] = useState<string | null>(null);\n  const [count, setCount] = useState<number | null>(null);\n  const [status, setStatus] = useState('Tap “Create” to build a geodatabase.');\n\n  async function create() {\n    setStatus('Creating…');\n    try {\n      const r = await createMobileGeodatabase({\n        tableName: TABLE,\n        geometryType: 'point',\n        fields: [{ name: 'name', type: 'text' }],\n      });\n      setPath(r.path);\n      setCount(r.featureCount);\n      setStatus(`Created with ${r.featureCount} features.`);\n    } catch (e) {\n      setStatus((e as { code?: string })?.code ?? String(e));\n    }\n  }\n\n  async function run(commit: boolean) {\n    if (!path) {\n      return;\n    }\n    setStatus(`Adding 3 features and ${commit ? 'committing' : 'rolling back'}…`);\n    try {\n      const r = await applyGeodatabaseTransaction(path, TABLE, 3, commit);\n      setCount(r.featureCount);\n      setStatus(\n        r.committed\n          ? `Committed → ${r.featureCount} features (persisted).`\n          : `Rolled back → ${r.featureCount} features (discarded).`\n      );\n    } catch (e) {\n      setStatus((e as { code?: string })?.code ?? String(e));\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.fill}>\n      <View style={styles.bar}>\n        <Button title=\"Create\" onPress={create} />\n        <Button title=\"Add 3 + commit\" onPress={() => run(true)} disabled={!path} />\n        <Button title=\"Add 3 + rollback\" onPress={() => run(false)} disabled={!path} />\n      </View>\n      <Text style={styles.count}>{count === null ? '—' : `${count} features`}</Text>\n      <Text style={styles.status}>{status}</Text>\n    </View>\n  );\n}\n","geometryeditor":"import {\n  ArcgisMapView,\n  type ArcgisGeometry,\n  type ArcgisMapViewRef,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function GeometryEditorScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [editing, setEditing] = useState(false);\n  const [result, setResult] = useState<GraphicSource[]>([]);\n  const [info, setInfo] = useState('Pick a geometry type, then tap the map to draw.');\n\n  async function start(geometryType: 'polyline' | 'polygon') {\n    setResult([]);\n    try {\n      await mapRef.current?.startGeometryEditor({ geometryType, tool: 'vertex', snapEnabled: true });\n      setEditing(true);\n      setInfo(`Drawing a ${geometryType}. Tap the map to add vertices, then Finish.`);\n    } catch (error) {\n      setInfo(`start failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function finish() {\n    try {\n      const geometry = (await mapRef.current?.stopGeometryEditor()) ?? null;\n      setEditing(false);\n      if (!geometry) {\n        setInfo('Nothing drawn.');\n        return;\n      }\n      setResult([\n        {\n          id: 'drawn',\n          geometry: geometry as ArcgisGeometry,\n          symbol: geometry.type === 'polyline' ? resultLine : resultFill,\n        },\n      ]);\n      setInfo(`Finished — drew a ${geometry.type}.`);\n    } catch (error) {\n      setEditing(false);\n      setInfo(`finish failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        <Button title=\"Polyline\" onPress={() => start('polyline')} disabled={editing} />\n        <Button title=\"Polygon\" onPress={() => start('polygon')} disabled={editing} />\n        <Button title=\"Finish\" onPress={finish} disabled={!editing} />\n      </View>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 100_000 },\n          featureLayers: [{ id: 'trailheads', url: TRAILHEADS_URL }],\n          graphics: result,\n        }}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","edit":"import { ArcgisMapView, type ArcgisMapViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { EDITABLE_LAYER_URL, SANTA_MONICA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Exercises the ref's `applyEdits` against an editable sample service. Success\n * requires a key/token with editing privileges; otherwise the service rejects\n * the edit and we surface the stable error code.\n */\n\nexport function EditScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [info, setInfo] = useState('Tap “Add feature” to push an edit to the service.');\n  const [lastAddedId, setLastAddedId] = useState<number | null>(null);\n\n  async function addFeature() {\n    try {\n      const result = await mapRef.current?.applyEdits({\n        layerId: 'damage',\n        adds: [{ attributes: { typdamage: 'Minor' }, point: SANTA_MONICA }],\n      });\n      const added = result?.addedObjectIds ?? [];\n      setLastAddedId(added[0] ?? null);\n      setInfo(`Added ${added.length} feature(s)${added[0] ? ` · OBJECTID ${added[0]}` : ''}.`);\n    } catch (error) {\n      setInfo(`add failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function deleteFeature() {\n    if (lastAddedId === null) {\n      setInfo('Add a feature first, then delete it.');\n      return;\n    }\n    try {\n      const result = await mapRef.current?.applyEdits({\n        layerId: 'damage',\n        deleteObjectIds: [lastAddedId],\n      });\n      setInfo(`Deleted ${result?.deletedCount ?? 0} feature(s).`);\n      setLastAddedId(null);\n    } catch (error) {\n      setInfo(`delete failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        <Button title=\"Add feature\" onPress={addFeature} />\n        <Button title=\"Delete last\" onPress={deleteFeature} />\n      </View>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 120_000 },\n          featureLayers: [{ id: 'damage', url: EDITABLE_LAYER_URL }],\n        }}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","featureform":"import {\n  ArcgisMapView,\n  type ArcgisMapViewRef,\n  type FeatureFormInfo,\n  type SingleTapEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { ScrollView, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SANTA_MONICA, TRAILHEADS_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Taps a feature and shows its editing form — title and field rows with current\n * values — via `showFeatureForm`. When the layer has no configured form, a\n * default form is generated from the feature's fields. Read-only view.\n */\n\nexport function FeatureFormScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [form, setForm] = useState<FeatureFormInfo | null>(null);\n  const [status, setStatus] = useState('Tap a feature to show its form.');\n\n  async function onTap(event: SingleTapEventPayload) {\n    setStatus('Identifying…');\n    setForm(null);\n    try {\n      const forms = (await mapRef.current?.showFeatureForm({ screenPoint: event.screenPoint })) ?? [];\n      if (forms.length === 0) {\n        setStatus('No form here — tap a feature.');\n        return;\n      }\n      setForm(forms[0]);\n      setStatus(`${forms[0].fields.length} field(s)`);\n    } catch (error) {\n      setStatus(`showFeatureForm failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISTopographic',\n          initialViewpoint: { center: SANTA_MONICA, scale: 100_000 },\n          featureLayers: [{ id: 'trailheads', url: TRAILHEADS_URL }],\n        }}\n        onSingleTap={({ nativeEvent }: { nativeEvent: SingleTapEventPayload }) => onTap(nativeEvent)}\n      />\n      {form ? (\n        <View style={styles.card}>\n          <Text style={styles.title}>{form.title || 'Edit feature'}</Text>\n          <ScrollView style={styles.fieldList}>\n            {form.fields.map((f, i) => (\n              <View key={`${f.label}-${i}`} style={styles.fieldRow}>\n                <Text style={styles.fieldLabel}>{f.label}</Text>\n                <Text style={styles.fieldValue}>{f.value || '—'}</Text>\n              </View>\n            ))}\n          </ScrollView>\n        </View>\n      ) : (\n        <Text style={screenStyles.status}>{status}</Text>\n      )}\n    </View>\n  );\n}\n","attachments":"import {\n  queryFeatureAttachments,\n  deleteFeatureAttachment,\n  type AttachmentInfo,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, FlatList, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { EDITABLE_LAYER_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A DamageAssessment feature that has attachments on the sample server.\n\nexport function AttachmentsScreen({ ready }: ScreenProps) {\n  const [attachments, setAttachments] = useState<AttachmentInfo[]>([]);\n  const [status, setStatus] = useState('Tap “List” to load attachments.');\n\n  async function list() {\n    setStatus('Loading attachments…');\n    try {\n      const result = await queryFeatureAttachments(EDITABLE_LAYER_URL, OBJECT_ID);\n      setAttachments(result);\n      setStatus(`${result.length} attachment(s) on feature ${OBJECT_ID}`);\n    } catch (error) {\n      setStatus(`list failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function removeFirst() {\n    if (attachments.length === 0) {\n      return;\n    }\n    setStatus('Deleting first attachment…');\n    try {\n      await deleteFeatureAttachment(EDITABLE_LAYER_URL, OBJECT_ID, attachments[0].id);\n      setStatus('Deleted. Reloading…');\n      await list();\n    } catch (error) {\n      setStatus(`delete failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, styles.pad]}>\n      <View style={styles.buttons}>\n        <Button title=\"List\" onPress={list} />\n        <Button title=\"Delete first\" onPress={removeFirst} disabled={attachments.length === 0} />\n      </View>\n      <Text style={styles.status}>{status}</Text>\n      <FlatList\n        data={attachments}\n        keyExtractor={(a) => String(a.id)}\n        renderItem={({ item }) => (\n          <View style={styles.row}>\n            <Text style={styles.name}>{item.name}</Text>\n            <Text style={styles.meta}>\n              {item.contentType} · {(item.size / 1024).toFixed(1)} KB\n            </Text>\n          </View>\n        )}\n      />\n    </View>\n  );\n}\n","updaterelated":"import { updateFeatureAttributes } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { EDITABLE_LAYER_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function UpdateRelatedScreen({ ready }: ScreenProps) {\n  const [current, setCurrent] = useState<string | null>(null);\n  const [status, setStatus] = useState('Tap “Read” to load the feature.');\n\n  async function read() {\n    setStatus('Reading feature…');\n    try {\n      const value = await readTypDamage();\n      setCurrent(value);\n      setStatus(`Current typdamage: ${value ?? '—'}`);\n    } catch (error) {\n      setStatus(`read failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function toggle() {\n    const next = current === 'Minor' ? 'Affected' : 'Minor';\n    setStatus(`Updating to “${next}”…`);\n    try {\n      await updateFeatureAttributes(EDITABLE_LAYER_URL, OBJECT_ID, { typdamage: next });\n      await read();\n    } catch (error) {\n      setStatus(`update failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={[screenStyles.fill, styles.pad]}>\n      <View style={styles.buttons}>\n        <Button title=\"Read\" onPress={read} />\n        <Button title=\"Toggle damage type\" onPress={toggle} disabled={current === null} />\n      </View>\n      <Text style={styles.value}>{current ?? '—'}</Text>\n      <Text style={styles.status}>{status}</Text>\n    </View>\n  );\n}\n","offline":"import {\n  startOfflineMapJob,\n  startPreplannedMapAreaJob,\n  deleteOfflineMap,\n  type OfflineMapJob,\n  type JobProgressEvent,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { NAPERVILLE_AREA, OFFLINE_WEB_MAP_ITEM_ID, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Exercises the offline-map job: start, live progress, cancel, and delete the\n * generated package. Needs a key/account permitted to take the sample web map\n * offline.\n */\n\nexport function OfflineScreen({ ready }: ScreenProps) {\n  const jobRef = useRef<OfflineMapJob | null>(null);\n  const [progress, setProgress] = useState<number | null>(null);\n  const [info, setInfo] = useState('Tap “Generate” to take the sample map offline.');\n  const [lastPath, setLastPath] = useState<string | null>(null);\n\n  async function generatePreplanned() {\n    if (jobRef.current) {\n      return;\n    }\n    setProgress(0);\n    setInfo('Finding preplanned area…');\n    try {\n      await runJob(() => startPreplannedMapAreaJob(OFFLINE_WEB_MAP_ITEM_ID, 0));\n    } catch (error) {\n      setInfo(`preplanned failed: ${(error as { code?: string }).code ?? 'error'}`);\n      setProgress(null);\n    }\n  }\n\n  async function runJob(makeJob: () => Promise<OfflineMapJob>) {\n    const job = await makeJob();\n    jobRef.current = job;\n    const sub = job.onProgress((event: JobProgressEvent) => {\n      setProgress(event.progress);\n      setInfo(`Status: ${event.status}`);\n    });\n    try {\n      const result = await job.result;\n      setLastPath(result.path);\n      setInfo(`Done: ${result.path}`);\n    } catch (error) {\n      const code = (error as { code?: string }).code ?? 'error';\n      setInfo(code === 'E_JOB_CANCELLED' ? 'Cancelled.' : `Failed: ${code}`);\n    } finally {\n      sub.remove();\n      jobRef.current = null;\n      setProgress(null);\n    }\n  }\n\n  async function generate() {\n    if (jobRef.current) {\n      return;\n    }\n    setProgress(0);\n    setInfo('Starting…');\n    try {\n      const job = await startOfflineMapJob({\n        webMapItemId: OFFLINE_WEB_MAP_ITEM_ID,\n        areaOfInterest: NAPERVILLE_AREA,\n      });\n      jobRef.current = job;\n      const sub = job.onProgress((event: JobProgressEvent) => {\n        setProgress(event.progress);\n        setInfo(`Status: ${event.status}`);\n      });\n      try {\n        const result = await job.result;\n        setLastPath(result.path);\n        setInfo(\n          result.layerErrors.length\n            ? `Done with ${result.layerErrors.length} layer error(s). First: ${result.layerErrors[0]}`\n            : `Done: ${result.path}`\n        );\n      } catch (error) {\n        const code = (error as { code?: string }).code ?? 'error';\n        setInfo(code === 'E_JOB_CANCELLED' ? 'Cancelled.' : `Failed: ${code}`);\n      } finally {\n        sub.remove();\n        jobRef.current = null;\n        setProgress(null);\n      }\n    } catch (error) {\n      setInfo(`start failed: ${(error as { code?: string }).code ?? 'error'}`);\n      setProgress(null);\n    }\n  }\n\n  async function cancel() {\n    await jobRef.current?.cancel();\n  }\n\n  async function remove() {\n    if (!lastPath) {\n      return;\n    }\n    try {\n      await deleteOfflineMap(lastPath);\n      setInfo(`Deleted ${lastPath}`);\n      setLastPath(null);\n    } catch (error) {\n      setInfo(`delete failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.container}>\n      <View style={styles.buttons}>\n        <Button title=\"Generate\" onPress={generate} disabled={progress !== null} />\n        <Button title=\"Preplanned\" onPress={generatePreplanned} disabled={progress !== null} />\n        <Button title=\"Cancel\" onPress={cancel} disabled={progress === null} />\n        <Button title=\"Delete\" onPress={remove} disabled={!lastPath} />\n      </View>\n      <Centered text={progress === null ? 'Idle' : `${progress}%`} />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","vectortiles":"import {\n  startExportVectorTilesJob,\n  deleteOfflineMap,\n  type ExportVectorTilesJob,\n  type JobProgressEvent,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { VECTOR_TILE_AREA, VECTOR_TILE_SERVICE_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Exercises the export-vector-tiles job: start, live progress, cancel, and\n * delete the generated `.vtpk` package. Needs a configured API key permitted to\n * export the ArcGIS basemap vector tiles.\n */\n\nexport function DownloadVectorTilesScreen({ ready }: ScreenProps) {\n  const jobRef = useRef<ExportVectorTilesJob | null>(null);\n  const [progress, setProgress] = useState<number | null>(null);\n  const [info, setInfo] = useState('Tap “Export” to download vector tiles for central London.');\n  const [lastPath, setLastPath] = useState<string | null>(null);\n\n  async function exportTiles() {\n    if (jobRef.current) {\n      return;\n    }\n    setProgress(0);\n    setInfo('Starting…');\n    try {\n      const job = await startExportVectorTilesJob({\n        serviceUrl: VECTOR_TILE_SERVICE_URL,\n        area: VECTOR_TILE_AREA,\n        maxScale: 10000,\n      });\n      jobRef.current = job;\n      const sub = job.onProgress((event: JobProgressEvent) => {\n        setProgress(event.progress);\n        setInfo(`Status: ${event.status}`);\n      });\n      try {\n        const result = await job.result;\n        setLastPath(result.path);\n        setInfo(`Done: ${result.path}`);\n      } catch (error) {\n        const code = (error as { code?: string }).code ?? 'error';\n        setInfo(code === 'E_JOB_CANCELLED' ? 'Cancelled.' : `Failed: ${code}`);\n      } finally {\n        sub.remove();\n        jobRef.current = null;\n        setProgress(null);\n      }\n    } catch (error) {\n      setInfo(`start failed: ${(error as { code?: string }).code ?? 'error'}`);\n      setProgress(null);\n    }\n  }\n\n  async function cancel() {\n    await jobRef.current?.cancel();\n  }\n\n  async function remove() {\n    if (!lastPath) {\n      return;\n    }\n    try {\n      await deleteOfflineMap(lastPath);\n      setInfo(`Deleted ${lastPath}`);\n      setLastPath(null);\n    } catch (error) {\n      setInfo(`delete failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.container}>\n      <View style={styles.buttons}>\n        <Button title=\"Export\" onPress={exportTiles} disabled={progress !== null} />\n        <Button title=\"Cancel\" onPress={cancel} disabled={progress === null} />\n        <Button title=\"Delete\" onPress={remove} disabled={!lastPath} />\n      </View>\n      <Centered text={progress === null ? 'Idle' : `${progress}%`} />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","geodatabase":"import {\n  startGenerateGeodatabaseJob,\n  startSyncGeodatabaseJob,\n  type JobProgressEvent,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { WILDFIRE_AREA, WILDFIRE_SYNC_SERVICE_URL, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Exercises geodatabase generate + sync jobs against Esri's public WildfireSync\n * sample service. Generate replicates the service into a local `.geodatabase`;\n * Sync pushes/pulls edits. Both reuse the shared job abstraction.\n */\n\nexport function GeodatabaseScreen({ ready }: ScreenProps) {\n  const [progress, setProgress] = useState<number | null>(null);\n  const [info, setInfo] = useState('Generate a local geodatabase, then sync it.');\n  const [path, setPath] = useState<string | null>(null);\n  const busy = useRef(false);\n\n  async function generate() {\n    if (busy.current) {\n      return;\n    }\n    busy.current = true;\n    setProgress(0);\n    setInfo('Generating…');\n    try {\n      const job = await startGenerateGeodatabaseJob({\n        featureServiceUrl: WILDFIRE_SYNC_SERVICE_URL,\n        areaOfInterest: WILDFIRE_AREA,\n      });\n      const sub = job.onProgress((e: JobProgressEvent) => setProgress(e.progress));\n      try {\n        const result = await job.result;\n        setPath(result.path);\n        setInfo(`Generated: ${result.path}`);\n      } finally {\n        sub.remove();\n      }\n    } catch (error) {\n      setInfo(`generate failed: ${(error as { code?: string }).code ?? 'error'}`);\n    } finally {\n      busy.current = false;\n      setProgress(null);\n    }\n  }\n\n  async function sync() {\n    if (busy.current || !path) {\n      return;\n    }\n    busy.current = true;\n    setProgress(0);\n    setInfo('Syncing…');\n    try {\n      const job = await startSyncGeodatabaseJob({\n        featureServiceUrl: WILDFIRE_SYNC_SERVICE_URL,\n        path,\n      });\n      const sub = job.onProgress((e: JobProgressEvent) => setProgress(e.progress));\n      try {\n        await job.result;\n        setInfo('Sync complete.');\n      } finally {\n        sub.remove();\n      }\n    } catch (error) {\n      setInfo(`sync failed: ${(error as { code?: string }).code ?? 'error'}`);\n    } finally {\n      busy.current = false;\n      setProgress(null);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.container}>\n      <View style={styles.buttons}>\n        <Button title=\"Generate\" onPress={generate} disabled={progress !== null} />\n        <Button title=\"Sync\" onPress={sync} disabled={progress !== null || !path} />\n      </View>\n      <Centered text={progress === null ? 'Idle' : `${progress}%`} />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","searchwebmap":"import {\n  ArcgisMapView,\n  searchWebMaps,\n  type WebMapSearchResult,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, FlatList, Pressable, StyleSheet, Text, TextInput, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Search ArcGIS Online for public web maps, then tap a result to open it in the\n * map view (via `webMapItemId`).\n */\n\nexport function SearchWebMapScreen({ ready }: ScreenProps) {\n  const [query, setQuery] = useState('watersheds');\n  const [results, setResults] = useState<WebMapSearchResult[]>([]);\n  const [status, setStatus] = useState('Search for a web map.');\n  const [openItemId, setOpenItemId] = useState<string | null>(null);\n\n  async function search() {\n    setStatus('Searching…');\n    setResults([]);\n    setOpenItemId(null);\n    try {\n      const found = await searchWebMaps(query);\n      setResults(found);\n      setStatus(found.length ? `${found.length} result(s) — tap to open` : 'No matches.');\n    } catch (error) {\n      setStatus(`search failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (openItemId) {\n    return (\n      <View style={screenStyles.fill}>\n        <View style={styles.bar}>\n          <Button title=\"← Back to results\" onPress={() => setOpenItemId(null)} />\n        </View>\n        <ArcgisMapView style={screenStyles.fill} map={{ webMapItemId: openItemId }} />\n      </View>\n    );\n  }\n  return (\n    <View style={[screenStyles.fill, styles.pad]}>\n      <TextInput\n        style={styles.input}\n        value={query}\n        onChangeText={setQuery}\n        placeholder=\"Search web maps\"\n        autoCapitalize=\"none\"\n      />\n      <Button title=\"Search\" onPress={search} />\n      <Text style={styles.status}>{status}</Text>\n      <FlatList\n        data={results}\n        keyExtractor={(item) => item.itemId}\n        renderItem={({ item }) => (\n          <Pressable style={styles.item} onPress={() => setOpenItemId(item.itemId)}>\n            <Text style={styles.title}>{item.title}</Text>\n            <Text style={styles.meta} numberOfLines={2}>\n              {item.snippet || 'No description'} · {item.owner}\n            </Text>\n          </Pressable>\n        )}\n      />\n    </View>\n  );\n}\n","auth":"import {\n  authenticate,\n  authenticateWithOAuth,\n  signOut,\n  type PortalUser,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, TextInput, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Set these to your registered ArcGIS OAuth application to exercise OAuth. The\n// redirect URI must match the config plugin's `oauthRedirectUri` in app.json.\n\nexport function AuthScreen({ ready }: ScreenProps) {\n  const [username, setUsername] = useState('');\n  const [password, setPassword] = useState('');\n  const [user, setUser] = useState<PortalUser | null>(null);\n  const [info, setInfo] = useState('Enter ArcGIS portal credentials, then sign in.');\n\n  async function signIn() {\n    try {\n      const result = await authenticate({ username, password });\n      setUser(result);\n      setInfo(`Signed in as ${result.fullName ?? result.username}.`);\n    } catch (error) {\n      setUser(null);\n      setInfo(`sign-in failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function signInOAuth() {\n    if (!OAUTH_CLIENT_ID) {\n      setInfo('Set OAUTH_CLIENT_ID (a registered ArcGIS OAuth app) to try OAuth sign-in.');\n      return;\n    }\n    setInfo('Opening browser for OAuth sign-in…');\n    try {\n      const result = await authenticateWithOAuth({\n        clientId: OAUTH_CLIENT_ID,\n        redirectUri: OAUTH_REDIRECT_URI,\n      });\n      setUser(result);\n      setInfo(`Signed in via OAuth as ${result.fullName ?? result.username}.`);\n    } catch (error) {\n      setUser(null);\n      setInfo(`OAuth sign-in failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function signOutUser() {\n    try {\n      await signOut();\n      setUser(null);\n      setInfo('Signed out.');\n    } catch (error) {\n      setInfo(`sign-out failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.form}>\n      <TextInput\n        style={styles.input}\n        placeholder=\"Username\"\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={username}\n        onChangeText={setUsername}\n      />\n      <TextInput\n        style={styles.input}\n        placeholder=\"Password\"\n        secureTextEntry\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={password}\n        onChangeText={setPassword}\n      />\n      <View style={styles.buttons}>\n        <Button title=\"Sign in\" onPress={signIn} disabled={!username || !password} />\n        <Button title=\"Sign out\" onPress={signOutUser} />\n      </View>\n      <Button title=\"Sign in with OAuth\" onPress={signInOAuth} />\n      {user ? <Text style={styles.detail}>{user.email ?? user.username}</Text> : null}\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","iwaauth":"/**\n * Enterprise authentication screens — Integrated Windows Authentication (IWA)\n * and PKI (client certificate) against an on-premises ArcGIS Enterprise portal.\n *\n * Both require enterprise infrastructure that ArcGIS Online cannot stand in for\n * (an IWA/PKI-protected portal, and for PKI a provisioned client certificate),\n * so out of the box these screens demonstrate the expected authentication\n * *failure* path. Point them at a real protected portal to exercise success.\n */\nimport { authenticateWithIWA, authenticateWithPKI, type PortalUser } from 'expo-arcgis-maps-sdk';\nimport { Platform } from 'expo-modules-core';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, TextInput, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Authenticate with Integrated Windows Authentication` — NTLM / Negotiate sign-in. */\n\nexport function IwaAuthScreen({ ready }: ScreenProps) {\n  const [portalUrl, setPortalUrl] = useState('https://webadaptor.example.com/portal');\n  const [username, setUsername] = useState('');\n  const [password, setPassword] = useState('');\n  const [user, setUser] = useState<PortalUser | null>(null);\n  const [info, setInfo] = useState('Enter an IWA-protected portal and Windows credentials.');\n\n  async function signIn() {\n    setInfo('Authenticating…');\n    try {\n      const result = await authenticateWithIWA({ portalUrl, username, password });\n      setUser(result);\n      setInfo(`Signed in as ${result.fullName ?? result.username}.`);\n    } catch (error) {\n      setUser(null);\n      setInfo(`IWA sign-in failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.form}>\n      <TextInput\n        style={styles.input}\n        placeholder=\"Portal URL\"\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={portalUrl}\n        onChangeText={setPortalUrl}\n      />\n      <TextInput\n        style={styles.input}\n        placeholder=\"DOMAIN\\username\"\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={username}\n        onChangeText={setUsername}\n      />\n      <TextInput\n        style={styles.input}\n        placeholder=\"Password\"\n        secureTextEntry\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={password}\n        onChangeText={setPassword}\n      />\n      <Button title=\"Sign in with IWA\" onPress={signIn} disabled={!portalUrl || !username} />\n      {user ? <Text style={styles.detail}>{user.email ?? user.username}</Text> : null}\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","pkiauth":"/**\n * Enterprise authentication screens — Integrated Windows Authentication (IWA)\n * and PKI (client certificate) against an on-premises ArcGIS Enterprise portal.\n *\n * Both require enterprise infrastructure that ArcGIS Online cannot stand in for\n * (an IWA/PKI-protected portal, and for PKI a provisioned client certificate),\n * so out of the box these screens demonstrate the expected authentication\n * *failure* path. Point them at a real protected portal to exercise success.\n */\nimport { authenticateWithIWA, authenticateWithPKI, type PortalUser } from 'expo-arcgis-maps-sdk';\nimport { Platform } from 'expo-modules-core';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, TextInput, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** `Authenticate with Integrated Windows Authentication` — NTLM / Negotiate sign-in. */\n\nexport function PkiAuthScreen({ ready }: ScreenProps) {\n  const [portalUrl, setPortalUrl] = useState('https://webadaptor.example.com/portal');\n  // iOS reads a PKCS#12 file; Android references a system-KeyChain alias.\n  const [certificate, setCertificate] = useState('');\n  const [password, setPassword] = useState('');\n  const [user, setUser] = useState<PortalUser | null>(null);\n  const isIos = Platform.OS === 'ios';\n  const [info, setInfo] = useState(\n    isIos\n      ? 'Enter a PKI-protected portal and a PKCS#12 certificate file path.'\n      : 'Enter a PKI-protected portal and a system-KeyChain certificate alias.'\n  );\n\n  async function signIn() {\n    setInfo('Authenticating…');\n    try {\n      const result = await authenticateWithPKI({\n        portalUrl,\n        certificatePath: isIos ? certificate : undefined,\n        password: isIos ? password : undefined,\n        certificateAlias: isIos ? undefined : certificate,\n      });\n      setUser(result);\n      setInfo(`Signed in as ${result.fullName ?? result.username}.`);\n    } catch (error) {\n      setUser(null);\n      setInfo(`PKI sign-in failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={styles.form}>\n      <TextInput\n        style={styles.input}\n        placeholder=\"Portal URL\"\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={portalUrl}\n        onChangeText={setPortalUrl}\n      />\n      <TextInput\n        style={styles.input}\n        placeholder={isIos ? 'Certificate file path (.pfx)' : 'KeyChain certificate alias'}\n        autoCapitalize=\"none\"\n        autoCorrect={false}\n        value={certificate}\n        onChangeText={setCertificate}\n      />\n      {isIos ? (\n        <TextInput\n          style={styles.input}\n          placeholder=\"Certificate password\"\n          secureTextEntry\n          autoCapitalize=\"none\"\n          autoCorrect={false}\n          value={password}\n          onChangeText={setPassword}\n        />\n      ) : null}\n      <Button title=\"Sign in with PKI\" onPress={signIn} disabled={!portalUrl || !certificate} />\n      {user ? <Text style={styles.detail}>{user.email ?? user.username}</Text> : null}\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","scene":"import { ArcgisSceneView, type ArcgisSceneViewRef } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport {\n  SF_BUILDINGS_SCENE_URL,\n  SF_CAMERA,\n  SF_CAMERA_WIDE,\n  type ScreenProps,\n} from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Renders the 3D `ArcgisSceneView`: an imagery basemap over world elevation with\n * San Francisco's 3D buildings scene layer, plus imperative camera moves.\n */\n\nexport function SceneScreen({ ready }: ScreenProps) {\n  const sceneRef = useRef<ArcgisSceneViewRef>(null);\n  const [info, setInfo] = useState('Loading 3D scene…');\n\n  async function flyTo(camera: typeof SF_CAMERA, label: string) {\n    try {\n      await sceneRef.current?.setCamera(camera, { durationMs: 2000 });\n      setInfo(`Camera: ${label}`);\n    } catch (error) {\n      setInfo(`setCamera failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        <Button title=\"Street level\" onPress={() => flyTo(SF_CAMERA, 'street level')} />\n        <Button title=\"Bird’s eye\" onPress={() => flyTo(SF_CAMERA_WIDE, 'bird’s eye')} />\n      </View>\n      <ArcgisSceneView\n        ref={sceneRef}\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          elevationEnabled: true,\n          sceneLayers: [{ id: 'sf-buildings', url: SF_BUILDINGS_SCENE_URL }],\n          initialCamera: SF_CAMERA,\n        }}\n        onSceneLoad={() => setInfo('Scene loaded. Tap a button to move the camera.')}\n        onSceneError={(e) => setInfo(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","webscene":"import { ArcgisSceneView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { WEB_SCENE_ITEM_ID, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Displays a 3D web scene loaded from an ArcGIS portal item\n * (`scene.webSceneItemId`). The web scene carries its own basemap, layers,\n * elevation, and initial camera.\n */\n\nexport function WebSceneScreen({ ready }: ScreenProps) {\n  const [info, setInfo] = useState('Loading web scene…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{ webSceneItemId: WEB_SCENE_ITEM_ID }}\n        onSceneLoad={() => setInfo('Web scene loaded (portal item).')}\n        onSceneError={(e) => setInfo(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","localscene":"import { ArcgisSceneView, type SceneViewingMode } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { SF_BUILDINGS_SCENE_URL, SF_CAMERA, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Displays a scene in local (planar) viewing mode and lets you switch to global\n * (globe) mode via `scene.viewingMode`. Local mode draws the scene on a flat\n * plane — suited to small, localized areas.\n */\n\nexport function LocalSceneScreen({ ready }: ScreenProps) {\n  const [mode, setMode] = useState<SceneViewingMode>('local');\n  const [info, setInfo] = useState('Loading local scene…');\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <View style={styles.buttons}>\n        <Button title=\"Local (flat)\" onPress={() => setMode('local')} />\n        <Button title=\"Global (globe)\" onPress={() => setMode('global')} />\n      </View>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          viewingMode: mode,\n          elevationEnabled: true,\n          sceneLayers: [{ id: 'sf-buildings', url: SF_BUILDINGS_SCENE_URL }],\n          initialCamera: SF_CAMERA,\n        }}\n        onSceneLoad={() => setInfo(`Scene loaded in ${mode} viewing mode.`)}\n        onSceneError={(e) => setInfo(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{info}</Text>\n    </View>\n  );\n}\n","sceneservice":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function SceneServiceLayerScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [\n          {\n            id: 'buildings',\n            url: 'https://basemaps3d.arcgis.com/arcgis/rest/services/Esri3D_Buildings_v1/SceneServer',\n          },\n        ],\n        initialCamera: cityCamera,\n      }}\n    />\n  );\n}\n","integratedmesh":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function IntegratedMeshLayerScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [\n          {\n            id: 'mesh',\n            type: 'integratedMesh',\n            url: 'https://tiles.arcgis.com/tiles/z2tnIkrLQ2BRzr6P/arcgis/rest/services/Girona_Spain/SceneServer',\n          },\n        ],\n        initialCamera: gironaCamera,\n      }}\n    />\n  );\n}\n","tiles3d":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function Add3DTilesLayerScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [\n          {\n            id: 'tiles',\n            type: '3dTiles',\n            url: 'https://tiles.arcgis.com/tiles/ZQgQTuoyBrtmoGdP/arcgis/rest/services/Stuttgart/3DTilesServer/tileset.json',\n          },\n        ],\n        initialCamera: stuttgartCamera,\n      }}\n    />\n  );\n}\n","terrainexaggeration":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function TerrainExaggerationScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        terrainExaggeration: 3,\n        initialCamera: terrainCamera,\n      }}\n    />\n  );\n}\n","surfaceconstraint":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function SurfaceNavigationConstraintScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        surfaceNavigationConstraint: 'stayAbove',\n        initialCamera: terrainCamera,\n      }}\n    />\n  );\n}\n","atmosphere":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function AtmosphereEffectScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        atmosphereEffect: 'realistic',\n        initialCamera: icelandCamera,\n      }}\n    />\n  );\n}\n","lighting":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function RealisticLightingScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sunLighting: 'lightAndShadows',\n        sceneLayers: [\n          {\n            id: 'buildings',\n            url: 'https://tiles.arcgis.com/tiles/P3ePLMYs2RVChkJx/arcgis/rest/services/DevA_BuildingShells/SceneServer',\n          },\n        ],\n        initialCamera: lightingCamera,\n      }}\n    />\n  );\n}\n","sceneenvironment":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function ConfigureSceneEnvironmentScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        atmosphereEffect: 'realistic',\n        sunLighting: 'lightAndShadows',\n        initialCamera: terrainCamera,\n      }}\n    />\n  );\n}\n","orbitcamera":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function OrbitCameraScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [\n          {\n            id: 'mesh',\n            type: 'integratedMesh',\n            url: 'https://tiles.arcgis.com/tiles/z2tnIkrLQ2BRzr6P/arcgis/rest/services/Girona_Spain/SceneServer',\n          },\n        ],\n        cameraController: {\n          type: 'orbitLocation',\n          target: { latitude: 41.9906, longitude: 2.8259, altitude: 50 },\n          distanceMeters: 800,\n        },\n      }}\n    />\n  );\n}\n","scenesymbol":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function SceneSymbolScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISTopographic',\n        elevationEnabled: true,\n        initialCamera: sceneSymbolCamera,\n        graphicsOverlays: [\n          {\n            id: 'scene-symbols',\n            surfacePlacement: 'absolute',\n            graphics: SCENE_SYMBOL_STYLES.map((style, i) => ({\n              id: `symbol-${style}`,\n              geometry: {\n                type: 'point',\n                point: { latitude: 49, longitude: 4.975 + 0.01 * i, altitude: 500 },\n              },\n              symbol: {\n                type: 'simpleMarkerScene',\n                style,\n                color: SCENE_SYMBOL_COLORS[i],\n                height: 200,\n                width: 200,\n                depth: 200,\n              },\n            })),\n          },\n        ],\n      }}\n    />\n  );\n}\n","extrudedgraphics":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function ExtrudedGraphicsScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISTopographic',\n        elevationEnabled: true,\n        initialCamera: extrudedGraphicsCamera,\n        graphicsOverlays: [\n          {\n            id: 'extruded',\n            surfacePlacement: 'drapedBillboarded',\n            renderer: {\n              type: 'simple',\n              symbol: {\n                type: 'simpleFill',\n                color: '#FF0000',\n                outline: { type: 'simpleLine', color: '#FFFFFF', width: 1 },\n              },\n            },\n            extrusion: { expression: '[height]', mode: 'baseHeight' },\n            graphics: extrudedGridGraphics(),\n          },\n        ],\n      }}\n    />\n  );\n}\n","mobilescenepackage":"/**\n * Scene screens that load large local data packages (`.mspk`, `.slpk`). The\n * data is provisioned exactly like the official ArcGIS samples app: downloaded\n * once from its ArcGIS Online portal item into the app cache, then passed to the\n * native view as a filesystem path.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** ArcGIS-Online portal-item data endpoint for a public item. */\n\nexport function MobileScenePackageScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedFile(\n    '7dd2f97bb007466ea939160d0de96a9d',\n    'philadelphia.mspk'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{ mobileScenePackagePath: path }}\n        onSceneLoad={() => setStatus('Scene loaded.')}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","pointcloud":"/**\n * Scene screens that load large local data packages (`.mspk`, `.slpk`). The\n * data is provisioned exactly like the official ArcGIS samples app: downloaded\n * once from its ArcGIS Online portal item into the app cache, then passed to the\n * native view as a filesystem path.\n */\nimport { Directory, File, Paths } from 'expo-file-system';\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** ArcGIS-Online portal-item data endpoint for a public item. */\n\nexport function PointCloudLayerScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedFile(\n    '34da965ca51d4c68aa9b3a38edb29e00',\n    'sandiego-north-balboa-pointcloud.slpk'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          elevationEnabled: true,\n          sceneLayers: [{ id: 'pointcloud', type: 'pointCloud', path }],\n          initialCamera: pointCloudCamera,\n        }}\n        onSceneLoad={() => setStatus('Scene loaded.')}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","buildingscenelayer":"/**\n * Building scene layer screens — display a BIM building scene layer, and apply a\n * solid building filter to it. Uses the official Redlands administration\n * building scene layer.\n */\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function BuildingSceneLayerScreen({ ready }: ScreenProps) {\n  const [status, setStatus] = useState('Loading building scene layer…');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISTopographic',\n          viewingMode: 'local',\n          elevationEnabled: true,\n          initialCamera: CAMERA,\n          sceneLayers: [{ id: 'building', type: 'building', url: BUILDING_SCENE_LAYER }],\n        }}\n        onSceneLoad={() => setStatus('Building scene layer loaded.')}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","filterbuildingscenelayer":"/**\n * Building scene layer screens — display a BIM building scene layer, and apply a\n * solid building filter to it. Uses the official Redlands administration\n * building scene layer.\n */\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FilterBuildingSceneLayerScreen({ ready }: ScreenProps) {\n  const [level, setLevel] = useState<number | null>(null);\n  const [status, setStatus] = useState('Whole building. Pick a level to filter.');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISTopographic',\n          viewingMode: 'local',\n          elevationEnabled: true,\n          initialCamera: CAMERA,\n          sceneLayers: [\n            {\n              id: 'building',\n              type: 'building',\n              url: BUILDING_SCENE_LAYER,\n              // A solid building filter: only the parts matching the where clause draw.\n              ...(level !== null ? { buildingFilterExpression: `BldgLevel = ${level}` } : {}),\n            },\n          ],\n        }}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <View style={styles.bar}>\n        {[null, 1, 2, 3].map((lvl) => (\n          <Pressable\n            key={String(lvl)}\n            style={[styles.chip, level === lvl && styles.chipOn]}\n            onPress={() => {\n              setLevel(lvl);\n              setStatus(lvl === null ? 'Whole building.' : `Filtered to level ${lvl}.`);\n            }}\n          >\n            <Text style={styles.chipText}>{lvl === null ? 'All' : `Lvl ${lvl}`}</Text>\n          </Pressable>\n        ))}\n        <Text style={styles.status}>{status}</Text>\n      </View>\n    </View>\n  );\n}\n","viewshed":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function ViewshedScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        sceneLayers: [{ id: 'buildings', url: brestBuildingsUrl }],\n        initialCamera: brestCamera,\n        analyses: [\n          {\n            // Official location/perspective: Point(-4.50, 48.4, z 100).\n            type: 'viewshed',\n            location: { latitude: 48.4, longitude: -4.5, altitude: 100 },\n            headingDegrees: 20,\n            pitchDegrees: 70,\n            horizontalAngleDegrees: 45,\n            verticalAngleDegrees: 90,\n            minDistanceMeters: 50,\n            maxDistanceMeters: 1000,\n          },\n        ],\n      }}\n    />\n  );\n}\n","lineofsight":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function LineOfSightScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISImagery',\n        elevationEnabled: true,\n        initialCamera: patagoniaCamera,\n        analyses: [\n          {\n            // Observer on a ridge, target across the valley; terrain occludes the line.\n            type: 'lineOfSight',\n            observer: { latitude: -49.35, longitude: -73.1, altitude: 3000 },\n            target: { latitude: -49.34, longitude: -73.06, altitude: 2000 },\n          },\n        ],\n      }}\n    />\n  );\n}\n","extrudedfeatures":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function ExtrudedFeaturesScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        basemap: 'arcGISTopographic',\n        elevationEnabled: true,\n        initialCamera: extrudedFeaturesCamera,\n        featureLayers: [\n          {\n            id: 'states',\n            url: censusStatesUrl,\n            renderer: {\n              type: 'simple',\n              symbol: {\n                type: 'simpleFill',\n                color: '#3F7FBF',\n                outline: { type: 'simpleLine', color: '#FFFFFF80', width: 1 },\n              },\n            },\n            extrusion: { expression: '[POP2007] / 10', mode: 'baseHeight' },\n          },\n        ],\n      }}\n    />\n  );\n}\n","labels3d":"/**\n * Scenes example screens, one per official ArcGIS sample so each shipped 3D\n * capability has its own demo (mirrors the Esri samples app).\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneSource,\n  type Camera,\n  type GraphicSource,\n} from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedZipFrames } from './provisioning';\n\n/** Shared scene demo: renders a scene source and reports load status. */\n\nexport function Labels3DScreen(props: ScreenProps) {\n  return (\n    <SceneDemo\n      {...props}\n      scene={{\n        webSceneItemId: '850dfee7d30f4d9da0ebca34a533c169',\n        webSceneLayerLabels: [\n          {\n            layerPath: ['Gas', 'Gas Main'],\n            labels: [\n              {\n                expression: 'Text($feature.INSTALLATIONDATE, `DD MMM YY`)',\n                arcade: true,\n                color: '#FFA500',\n                size: 16,\n                haloColor: '#FFFFFF',\n                haloWidth: 2,\n                placement: 'lineAboveAlong',\n              },\n            ],\n          },\n        ],\n      }}\n    />\n  );\n}\n","rasterelevation":"/**\n * Scene screens that build the base surface from an explicit local elevation\n * source, mirroring the official samples. Both provision the official Monterey\n * elevation data from its ArcGIS Online portal item and frame it with the\n * sample's own camera; the surface then shows real terrain relief.\n */\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedFile, useProvisionedZip } from './provisioning';\n\n// The camera both official samples use to frame the Monterey terrain.\n\nexport function RasterElevationScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedZip(\n    '98092369c4ae4d549bbbd45dba993ebc',\n    'monterey-elevation-raster',\n    'MontereyElevation.dt2'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          elevationSources: [{ type: 'raster', path }],\n          initialCamera: MONTEREY_CAMERA,\n        }}\n        onSceneLoad={() => setStatus('Scene loaded (raster elevation).')}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","tilepackageelevation":"/**\n * Scene screens that build the base surface from an explicit local elevation\n * source, mirroring the official samples. Both provision the official Monterey\n * elevation data from its ArcGIS Online portal item and frame it with the\n * sample's own camera; the surface then shows real terrain relief.\n */\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\nimport { useProvisionedFile, useProvisionedZip } from './provisioning';\n\n// The camera both official samples use to frame the Monterey terrain.\n\nexport function TilePackageElevationScreen({ ready }: ScreenProps) {\n  const { path, status, setStatus } = useProvisionedFile(\n    '52ca74b4ba8042b78b3c653696f34a9c',\n    'MontereyElevation.tpkx'\n  );\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (!path) {\n    return <Centered text={status} />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          elevationSources: [{ type: 'tilePackage', path }],\n          initialCamera: MONTEREY_CAMERA,\n        }}\n        onSceneLoad={() => setStatus('Scene loaded (tile-package elevation).')}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","surfaceelevation":"/**\n * `Get elevation at point on surface` — queries the scene's base surface for the\n * elevation at a geographic point via the `getSurfaceElevation` ref method and\n * shows the result. Frames the Everest massif so the returned metres are\n * intuitively large.\n */\nimport { ArcgisSceneView, type ArcgisSceneViewRef, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Mount Everest summit — the surface elevation here is ~8.8 km.\n\nexport function SurfaceElevationScreen({ ready }: ScreenProps) {\n  const sceneRef = useRef<ArcgisSceneViewRef>(null);\n  const [status, setStatus] = useState('Tap \"Get elevation\" to query the surface at Everest.');\n\n  async function query() {\n    setStatus('Querying elevation…');\n    try {\n      const meters = await sceneRef.current?.getSurfaceElevation(EVEREST);\n      setStatus(meters == null ? 'No elevation returned.' : `Elevation: ${Math.round(meters)} m`);\n    } catch (error) {\n      setStatus(`getSurfaceElevation failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        ref={sceneRef}\n        style={screenStyles.fill}\n        scene={{ basemap: 'arcGISImagery', initialCamera: EVEREST_CAMERA }}\n        onSceneError={(e) => setStatus(`scene error: ${e.nativeEvent.code}`)}\n      />\n      <View style={styles.bar}>\n        <Pressable style={styles.button} onPress={query}>\n          <Text style={styles.buttonText}>Get elevation</Text>\n        </Pressable>\n        <Text style={styles.status}>{status}</Text>\n      </View>\n    </View>\n  );\n}\n","surfaceplacement":"/**\n * `Set surface placement mode` — draws the same marker at the same altitude\n * under each {@link SurfacePlacement} mode so their vertical placement can be\n * compared: `drapedFlat`/`drapedBillboarded` sit on the terrain, `relative`\n * floats above the surface, and `absolute` floats at a fixed height above sea\n * level. Each mode is a separate graphics overlay (placement is per-overlay).\n */\nimport { ArcgisSceneView, type Camera, type SurfacePlacement } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// A mountainous location (the Alps near Zermatt) so terrain relief makes the\n// draped vs. relative vs. absolute placement visibly different.\n\nexport function SurfacePlacementScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: CAMERA,\n          // One overlay per placement mode, each a sphere at the same location\n          // and altitude (2500 m) — the mode decides where the sphere ends up.\n          graphicsOverlays: MODES.map(({ placement, color }, i) => ({\n            id: `placement-${placement}`,\n            surfacePlacement: placement,\n            graphics: [\n              {\n                id: `marker-${placement}`,\n                geometry: {\n                  type: 'point',\n                  point: {\n                    latitude: CENTER.latitude,\n                    longitude: CENTER.longitude + 0.004 * i,\n                    altitude: 2500,\n                  },\n                },\n                symbol: {\n                  type: 'simpleMarkerScene',\n                  style: 'sphere',\n                  color,\n                  height: 120,\n                  width: 120,\n                  depth: 120,\n                },\n              },\n            ],\n          })),\n        }}\n      />\n    </View>\n  );\n}\n","animategraphic":"/**\n * `Animate 3D graphic` — moves a graphic through the scene over time. A marker\n * orbits a fixed centre at a constant altitude; JS advances the angle on an\n * interval and updates the graphic's geometry, which the native view reconciles\n * by id (so only the moved graphic is updated, not the whole overlay).\n */\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { useEffect, useState } from 'react';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function AnimateGraphicScreen({ ready }: ScreenProps) {\n  const [angle, setAngle] = useState(0);\n\n  useEffect(() => {\n    // ~15 fps orbit; the graphic is reconciled by id each tick.\n    const timer = setInterval(() => setAngle((a) => (a + 4) % 360), 66);\n    return () => clearInterval(timer);\n  }, []);\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  const rad = (angle * Math.PI) / 180;\n  const point = {\n    latitude: CENTER.latitude + RADIUS_DEG * Math.cos(rad),\n    longitude: CENTER.longitude + RADIUS_DEG * Math.sin(rad),\n    altitude: ALTITUDE,\n  };\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: CAMERA,\n          graphicsOverlays: [\n            {\n              id: 'orbit',\n              surfacePlacement: 'absolute',\n              graphics: [\n                {\n                  id: 'mover',\n                  geometry: { type: 'point', point },\n                  symbol: {\n                    type: 'simpleMarkerScene',\n                    style: 'cone',\n                    color: '#E4572E',\n                    height: 400,\n                    width: 200,\n                    depth: 200,\n                  },\n                },\n              ],\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","filterfeatures":"/**\n * `Filter features in scene` — restricts which features of a 3D scene layer are\n * drawn to a polygon region. Loads the San Francisco buildings scene layer (the\n * official sample's data) and applies a `disjoint` polygon filter over a\n * downtown block, so the buildings inside that block are hidden.\n */\nimport { ArcgisSceneView, type Camera, type GeographicPoint } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function FilterFeaturesScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: CAMERA,\n          sceneLayers: [\n            {\n              id: 'sf-buildings',\n              type: 'scene',\n              url: SF_BUILDINGS,\n              polygonFilter: { polygons: [HOLE], spatialRelationship: 'disjoint' },\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","matchviewpoint":"/**\n * `Match viewpoint of geo views` — keeps a 2D map and a 3D scene framed on the\n * same place. Panning/zooming the map (top) emits `onViewpointChange`, which\n * drives the scene's camera (bottom) to the same centre, with an altitude\n * derived from the map scale.\n *\n * This mirrors the official sample's map→scene direction. Driving the map from\n * the scene would need a scene camera-change event, which the scene view does\n * not yet emit, so the sync here is one-way.\n */\nimport {\n  ArcgisMapView,\n  ArcgisSceneView,\n  type ArcgisSceneViewRef,\n  type ViewpointChangeEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef } from 'react';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function MatchViewpointScreen({ ready }: ScreenProps) {\n  const sceneRef = useRef<ArcgisSceneViewRef>(null);\n\n  function onViewpointChange({ center, scale }: ViewpointChangeEventPayload) {\n    // Camera altitude scales with the map's scale denominator so zooming the map\n    // pulls the scene camera in and out too.\n    const altitude = Math.max(800, scale * 0.5);\n    sceneRef.current\n      ?.setCamera({ latitude: center.latitude, longitude: center.longitude, altitude, pitch: 65 })\n      .catch(() => {});\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={styles.half}\n        map={{ basemap: 'arcGISImagery', initialViewpoint: { center: START, scale: 25_000 } }}\n        onViewpointChange={({ nativeEvent }) => onViewpointChange(nativeEvent)}\n      />\n      <ArcgisSceneView\n        ref={sceneRef}\n        style={styles.half}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: { latitude: START.latitude, longitude: START.longitude, altitude: 12500, pitch: 65 },\n        }}\n      />\n    </View>\n  );\n}\n","distancecomposite":"/**\n * `Style point with distance composite scene symbol` — a point whose 3D marker\n * swaps by camera distance: a large red cone up close, an orange sphere at mid\n * range, and a small blue cube far away. Pinch-zoom the scene to move the camera\n * in and out and watch the marker change.\n */\nimport { ArcgisSceneView, type Camera } from 'expo-arcgis-maps-sdk';\nimport { View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function DistanceCompositeScreen({ ready }: ScreenProps) {\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: CAMERA,\n          graphicsOverlays: [\n            {\n              id: 'distance-composite',\n              surfacePlacement: 'absolute',\n              graphics: [\n                {\n                  id: 'marker',\n                  geometry: { type: 'point', point: POINT },\n                  symbol: {\n                    type: 'distanceCompositeScene',\n                    ranges: [\n                      {\n                        symbol: {\n                          type: 'simpleMarkerScene',\n                          style: 'cone',\n                          color: '#E4572E',\n                          height: 700,\n                          width: 400,\n                          depth: 400,\n                        },\n                        minDistance: 0,\n                        maxDistance: 2000,\n                      },\n                      {\n                        symbol: {\n                          type: 'simpleMarkerScene',\n                          style: 'sphere',\n                          color: '#F3A712',\n                          height: 500,\n                          width: 500,\n                          depth: 500,\n                        },\n                        minDistance: 2000,\n                        maxDistance: 8000,\n                      },\n                      {\n                        symbol: {\n                          type: 'simpleMarkerScene',\n                          style: 'cube',\n                          color: '#3D5A80',\n                          height: 400,\n                          width: 400,\n                          depth: 400,\n                        },\n                        minDistance: 8000,\n                        maxDistance: 40000,\n                      },\n                    ],\n                  },\n                },\n              ],\n            },\n          ],\n        }}\n      />\n    </View>\n  );\n}\n","sceneselection":"/**\n * `Select features in scene layer` — tap a building in the Brest buildings scene\n * layer (the official sample's data) to select it. `onSingleTap` gives the\n * screen point; `selectSceneFeatures` identifies the scene-layer features there\n * and highlights them. \"Clear\" removes the selection.\n */\nimport {\n  ArcgisSceneView,\n  type ArcgisSceneViewRef,\n  type Camera,\n  type SingleTapEventPayload,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function SceneSelectionScreen({ ready }: ScreenProps) {\n  const sceneRef = useRef<ArcgisSceneViewRef>(null);\n  const [status, setStatus] = useState('Tap a building to select it.');\n\n  async function onTap(event: SingleTapEventPayload) {\n    try {\n      const count = await sceneRef.current?.selectSceneFeatures({ screenPoint: event.screenPoint });\n      setStatus(count ? `${count} feature(s) selected` : 'No feature here — tap a building.');\n    } catch (error) {\n      setStatus(`selectSceneFeatures failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n\n  async function clear() {\n    try {\n      await sceneRef.current?.clearSceneSelection();\n      setStatus('Selection cleared.');\n    } catch {\n      setStatus('clearSceneSelection failed.');\n    }\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisSceneView\n        ref={sceneRef}\n        style={screenStyles.fill}\n        scene={{\n          basemap: 'arcGISImagery',\n          initialCamera: CAMERA,\n          sceneLayers: [{ id: 'brest', type: 'scene', url: BREST_BUILDINGS }],\n        }}\n        onSingleTap={({ nativeEvent }: { nativeEvent: SingleTapEventPayload }) => onTap(nativeEvent)}\n      />\n      <View style={styles.bar}>\n        <Pressable style={styles.button} onPress={clear}>\n          <Text style={styles.buttonText}>Clear</Text>\n        </Pressable>\n        <Text style={styles.status}>{status}</Text>\n      </View>\n    </View>\n  );\n}\n","untrace":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function TraceScreen(props: ScreenProps) {\n  return <ActionScreen {...props} label=\"Run connected trace\" initial=\"Tap to trace connected features.\" action={() => runTrace('connected')} />;\n}\n","unsubnetwork":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function SubnetworkTraceScreen(props: ScreenProps) {\n  return <ActionScreen {...props} label=\"Run subnetwork trace\" initial=\"Tap to trace the subnetwork.\" action={() => runTrace('subnetwork')} />;\n}\n","unisolation":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function IsolationTraceScreen(props: ScreenProps) {\n  const barrier: UtilityFeatureSelector = { layerUrl: DEVICE_LAYER, whereClause: \"assetgroup = 3 AND assettype = 8\" };\n  return <ActionScreen {...props} label=\"Run isolation trace\" initial=\"Tap to run an isolation trace.\" action={() => runTrace('isolation', [barrier])} />;\n}\n","unloadreport":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function LoadReportScreen(props: ScreenProps) {\n  return (\n    <ActionScreen\n      {...props}\n      label=\"Create load report\"\n      initial=\"Tap to build a load report from a subnetwork trace.\"\n      action={async () => {\n        const result = await traceUtilityNetwork({\n          serviceUrl: UN_SERVICE,\n          traceType: 'subnetwork',\n          startingPoints: [STARTING_POINT],\n        });\n        return `Load report — ${traceReport(result.byAssetGroup)}`;\n      }}\n    />\n  );\n}\n","unvalidate":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ValidateTopologyScreen(props: ScreenProps) {\n  return (\n    <ActionScreen\n      {...props}\n      label=\"Validate topology\"\n      initial=\"Tap to validate the network topology.\"\n      action={async () => {\n        const result = await validateUtilityNetworkTopology({\n          serviceUrl: UN_SERVICE,\n          extent: NAPERVILLE_EXTENT,\n        });\n        return result.hasErrors ? 'Topology has dirty areas / errors.' : 'Topology is valid.';\n      }}\n    />\n  );\n}\n","unassociations":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function AssociationsScreen(props: ScreenProps) {\n  return (\n    <ActionScreen\n      {...props}\n      label=\"Get associations\"\n      initial=\"Tap to fetch associations in the extent.\"\n      action={async () => {\n        const result = await getUtilityAssociations({ serviceUrl: UN_SERVICE, extent: NAPERVILLE_EXTENT });\n        return `${result.associations.length} association(s).`;\n      }}\n    />\n  );\n}\n","uncontainer":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function ContainerContentsScreen(props: ScreenProps) {\n  return (\n    <ActionScreen\n      {...props}\n      label=\"Get container contents\"\n      initial=\"Tap to list containment associations.\"\n      action={async () => {\n        const result = await getUtilityAssociations({\n          serviceUrl: UN_SERVICE,\n          extent: NAPERVILLE_EXTENT,\n          kind: 'containment',\n        });\n        return `${result.associations.length} contained item(s).`;\n      }}\n    />\n  );\n}\n","unsnap":"/**\n * Utility-network screens — trace variants, load report, topology validation,\n * associations, container contents, and UN-rule snapping. These use the official\n * Naperville Electric utility network (a signed-in user with access is required\n * to run them, so they are build-verified here).\n */\nimport {\n  ArcgisMapView,\n  getUtilityAssociations,\n  traceUtilityNetwork,\n  validateUtilityNetworkTopology,\n  type ArcgisMapViewRef,\n  type UtilityFeatureSelector,\n  type UtilityTraceType,\n} from 'expo-arcgis-maps-sdk';\nimport { useRef, useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\nexport function UtilityNetworkSnapScreen({ ready }: ScreenProps) {\n  const mapRef = useRef<ArcgisMapViewRef>(null);\n  const [editing, setEditing] = useState(false);\n  const [status, setStatus] = useState('Start editing; new vertices snap to nearby network features.');\n\n  async function start() {\n    try {\n      await mapRef.current?.startGeometryEditor({ geometryType: 'polyline', tool: 'vertex', snapEnabled: true });\n      setEditing(true);\n      setStatus('Snapping is on — tap near a feature to snap the vertex to it.');\n    } catch (error) {\n      setStatus(`start failed: ${(error as { code?: string }).code ?? 'error'}`);\n    }\n  }\n  async function finish() {\n    await mapRef.current?.stopGeometryEditor();\n    setEditing(false);\n    setStatus('Finished the snapped edit.');\n  }\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        ref={mapRef}\n        style={screenStyles.fill}\n        map={{\n          basemap: 'arcGISStreetsNight',\n          initialViewpoint: { center: NAPERVILLE, scale: 5_000 },\n          layers: [{ id: 'devices', type: 'mapImage', url: UN_SERVICE }],\n        }}\n      />\n      <View style={{ padding: 6, alignItems: 'center' }}>\n        {editing ? <Button title=\"Finish\" onPress={finish} /> : <Button title=\"Start snapped edit\" onPress={start} />}\n      </View>\n      <Text style={screenStyles.status}>{status}</Text>\n    </View>\n  );\n}\n","artabletop":"/**\n * Augmented-reality screens — the toolkit's three AR scene views (world-scale,\n * tabletop, flyover) exposed through {@link ArcgisArView}. AR needs ARKit / a\n * physical iPhone (it does not run in the iOS Simulator) or an ARCore device /\n * emulator, so these are gated with {@link isArSupported}: on an incapable\n * device they show a notice instead of the camera view.\n *\n * Scene data mirrors the official ArcGIS Maps SDK Toolkit AR examples.\n */\nimport {\n  ArcgisArView,\n  isArSupported,\n  type ArcgisArViewRef,\n  type ArTrackingState,\n  type GraphicSource,\n  type SceneGraphicsOverlay,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Portland, OR — the official tabletop example's building-shells anchor.\n\nexport function ArTabletopScreen({ ready }: ScreenProps) {\n  const supported = useArSupport();\n  const [status, setStatus] = useState('Point the camera at a flat surface.');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (supported === false) {\n    return <Centered text=\"Augmented reality is not available on this device.\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisArView\n        style={screenStyles.fill}\n        mode=\"tabletop\"\n        anchor={PORTLAND}\n        translationFactor={1000}\n        clippingDistanceMeters={400}\n        scene={{\n          basemap: 'arcGISImagery',\n          elevationEnabled: true,\n          sceneLayers: [{ id: 'buildings', type: 'scene', url: BUILDINGS_SCENE_LAYER }],\n        }}\n        onTrackingStateChange={(e) => setStatus(trackingLabel(e.nativeEvent.state))}\n        onArError={(e) => setStatus(`AR error: ${e.nativeEvent.code}`)}\n      />\n      <StatusBar text={status} />\n    </View>\n  );\n}\n","arflyover":"/**\n * Augmented-reality screens — the toolkit's three AR scene views (world-scale,\n * tabletop, flyover) exposed through {@link ArcgisArView}. AR needs ARKit / a\n * physical iPhone (it does not run in the iOS Simulator) or an ARCore device /\n * emulator, so these are gated with {@link isArSupported}: on an incapable\n * device they show a notice instead of the camera view.\n *\n * Scene data mirrors the official ArcGIS Maps SDK Toolkit AR examples.\n */\nimport {\n  ArcgisArView,\n  isArSupported,\n  type ArcgisArViewRef,\n  type ArTrackingState,\n  type GraphicSource,\n  type SceneGraphicsOverlay,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Portland, OR — the official tabletop example's building-shells anchor.\n\nexport function ArFlyoverScreen({ ready }: ScreenProps) {\n  const supported = useArSupport();\n  const [status, setStatus] = useState('Move the device to fly over the scene.');\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (supported === false) {\n    return <Centered text=\"Augmented reality is not available on this device.\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisArView\n        style={screenStyles.fill}\n        mode=\"flyover\"\n        initialCamera={ROTTERDAM}\n        translationFactor={1000}\n        scene={{ webSceneItemId: FLYOVER_WEB_SCENE }}\n        onTrackingStateChange={(e) => setStatus(trackingLabel(e.nativeEvent.state))}\n        onArError={(e) => setStatus(`AR error: ${e.nativeEvent.code}`)}\n      />\n      <StatusBar text={status} />\n    </View>\n  );\n}\n","arcollect":"/**\n * Augmented-reality screens — the toolkit's three AR scene views (world-scale,\n * tabletop, flyover) exposed through {@link ArcgisArView}. AR needs ARKit / a\n * physical iPhone (it does not run in the iOS Simulator) or an ARCore device /\n * emulator, so these are gated with {@link isArSupported}: on an incapable\n * device they show a notice instead of the camera view.\n *\n * Scene data mirrors the official ArcGIS Maps SDK Toolkit AR examples.\n */\nimport {\n  ArcgisArView,\n  isArSupported,\n  type ArcgisArViewRef,\n  type ArTrackingState,\n  type GraphicSource,\n  type SceneGraphicsOverlay,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Portland, OR — the official tabletop example's building-shells anchor.\n\nexport function ArCollectScreen({ ready }: ScreenProps) {\n  const supported = useArSupport();\n  const [graphics, setGraphics] = useState<GraphicSource[]>([]);\n  const [status, setStatus] = useState('Tap the ground to collect a point.');\n\n  const overlay: SceneGraphicsOverlay = {\n    id: 'collected',\n    surfacePlacement: 'relative',\n    graphics,\n  };\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (supported === false) {\n    return <Centered text=\"Augmented reality is not available on this device.\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisArView\n        style={screenStyles.fill}\n        mode=\"worldScale\"\n        scene={{ basemap: 'arcGISImagery', elevationEnabled: true, graphicsOverlays: [overlay] }}\n        onSingleTap={(e) => {\n          const point = e.nativeEvent.mapPoint;\n          if (!point) return;\n          setGraphics((prev) => [\n            ...prev,\n            {\n              id: `pt-${prev.length}`,\n              geometry: { type: 'point', point: { ...point, altitude: 1 } },\n              symbol: {\n                type: 'simpleMarkerScene',\n                style: 'sphere',\n                color: '#E4572E',\n                height: 0.5,\n                width: 0.5,\n                depth: 0.5,\n              },\n            },\n          ]);\n          setStatus(`Collected ${graphics.length + 1} point(s).`);\n        }}\n        onTrackingStateChange={(e) => setStatus(trackingLabel(e.nativeEvent.state))}\n        onArError={(e) => setStatus(`AR error: ${e.nativeEvent.code}`)}\n      />\n      <StatusBar text={status} />\n    </View>\n  );\n}\n","arnavigate":"/**\n * Augmented-reality screens — the toolkit's three AR scene views (world-scale,\n * tabletop, flyover) exposed through {@link ArcgisArView}. AR needs ARKit / a\n * physical iPhone (it does not run in the iOS Simulator) or an ARCore device /\n * emulator, so these are gated with {@link isArSupported}: on an incapable\n * device they show a notice instead of the camera view.\n *\n * Scene data mirrors the official ArcGIS Maps SDK Toolkit AR examples.\n */\nimport {\n  ArcgisArView,\n  isArSupported,\n  type ArcgisArViewRef,\n  type ArTrackingState,\n  type GraphicSource,\n  type SceneGraphicsOverlay,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Portland, OR — the official tabletop example's building-shells anchor.\n\nexport function ArNavigateScreen({ ready }: ScreenProps) {\n  const supported = useArSupport();\n  const [status, setStatus] = useState('Follow the route line ahead of you.');\n\n  // A short demo route near the device's default location, drawn just above the\n  // surface so it reads as an on-the-ground navigation line.\n  const routeOverlay: SceneGraphicsOverlay = {\n    id: 'route',\n    surfacePlacement: 'relative',\n    graphics: [\n      {\n        id: 'route-line',\n        geometry: {\n          type: 'polyline',\n          path: [\n            { latitude: 34.056, longitude: -117.195, altitude: 1 },\n            { latitude: 34.057, longitude: -117.194, altitude: 1 },\n            { latitude: 34.058, longitude: -117.1925, altitude: 1 },\n          ],\n        },\n        symbol: { type: 'simpleLine', color: '#2F7D6E', width: 4 },\n      },\n    ],\n  };\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (supported === false) {\n    return <Centered text=\"Augmented reality is not available on this device.\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisArView\n        style={screenStyles.fill}\n        mode=\"worldScale\"\n        scene={{ basemap: 'arcGISImagery', elevationEnabled: true, graphicsOverlays: [routeOverlay] }}\n        onTrackingStateChange={(e) => setStatus(trackingLabel(e.nativeEvent.state))}\n        onArError={(e) => setStatus(`AR error: ${e.nativeEvent.code}`)}\n      />\n      <StatusBar text={status} />\n    </View>\n  );\n}\n","arhidden":"/**\n * Augmented-reality screens — the toolkit's three AR scene views (world-scale,\n * tabletop, flyover) exposed through {@link ArcgisArView}. AR needs ARKit / a\n * physical iPhone (it does not run in the iOS Simulator) or an ARCore device /\n * emulator, so these are gated with {@link isArSupported}: on an incapable\n * device they show a notice instead of the camera view.\n *\n * Scene data mirrors the official ArcGIS Maps SDK Toolkit AR examples.\n */\nimport {\n  ArcgisArView,\n  isArSupported,\n  type ArcgisArViewRef,\n  type ArTrackingState,\n  type GraphicSource,\n  type SceneGraphicsOverlay,\n} from 'expo-arcgis-maps-sdk';\nimport { useEffect, useRef, useState } from 'react';\nimport { Pressable, StyleSheet, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n// Portland, OR — the official tabletop example's building-shells anchor.\n\nexport function ArHiddenInfrastructureScreen({ ready }: ScreenProps) {\n  const supported = useArSupport();\n  const ref = useRef<ArcgisArViewRef>(null);\n  const [status, setStatus] = useState('Look down to see the buried pipe.');\n\n  // A buried utility line: absolute placement at negative altitude puts it below\n  // the surface, so world-scale AR shows the \"hidden\" infrastructure underfoot.\n  const pipeOverlay: SceneGraphicsOverlay = {\n    id: 'pipe',\n    surfacePlacement: 'absolute',\n    graphics: [\n      {\n        id: 'pipe-line',\n        geometry: {\n          type: 'polyline',\n          path: [\n            { latitude: 34.056, longitude: -117.195, altitude: -2 },\n            { latitude: 34.057, longitude: -117.1945, altitude: -2 },\n          ],\n        },\n        symbol: { type: 'simpleLine', color: '#F3A712', width: 6 },\n      },\n    ],\n  };\n\n  if (!ready) {\n    return <Centered text=\"Waiting for configuration…\" />;\n  }\n  if (supported === false) {\n    return <Centered text=\"Augmented reality is not available on this device.\" />;\n  }\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisArView\n        ref={ref}\n        style={screenStyles.fill}\n        mode=\"worldScale\"\n        trackingMode=\"geo\"\n        scene={{\n          basemap: 'arcGISImagery',\n          elevationEnabled: true,\n          surfaceNavigationConstraint: 'none',\n          graphicsOverlays: [pipeOverlay],\n        }}\n        onTrackingStateChange={(e) => setStatus(trackingLabel(e.nativeEvent.state))}\n        onArError={(e) => setStatus(`AR error: ${e.nativeEvent.code}`)}\n      />\n      <View style={styles.bar}>\n        <Pressable\n          style={styles.button}\n          onPress={async () => {\n            try {\n              const camera = await ref.current?.getCurrentCamera();\n              setStatus(\n                camera\n                  ? `Camera: ${camera.latitude.toFixed(4)}, ${camera.longitude.toFixed(4)}`\n                  : 'No camera yet.'\n              );\n            } catch (error) {\n              setStatus(`getCurrentCamera failed: ${(error as { code?: string }).code ?? 'error'}`);\n            }\n          }}\n        >\n          <Text style={styles.buttonText}>Where am I?</Text>\n        </Pressable>\n        <Text style={styles.status}>{status}</Text>\n      </View>\n    </View>\n  );\n}\n","remount":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Button, Text, View } from 'react-native';\n\nimport { Centered } from '../Centered';\nimport { LONDON, type ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/** Toggles the map on/off to exercise mount/unmount/remount safety. */\n\nexport function RemountScreen({ ready }: ScreenProps) {\n  const [mounted, setMounted] = useState(true);\n  const [mountCount, setMountCount] = useState(1);\n\n  return (\n    <View style={screenStyles.fill}>\n      <Button\n        title={mounted ? 'Unmount map' : 'Mount map'}\n        onPress={() => {\n          if (!mounted) {\n            setMountCount((n) => n + 1);\n          }\n          setMounted((m) => !m);\n        }}\n      />\n      <Text style={screenStyles.status}>Mounts: {mountCount}</Text>\n      <View style={screenStyles.fill}>\n        {mounted && ready ? (\n          <ArcgisMapView\n            style={screenStyles.fill}\n            map={{ basemap: 'arcGISLightGray', initialViewpoint: { center: LONDON, scale: 50_000 } }}\n          />\n        ) : (\n          <Centered text={mounted ? 'Waiting for configuration…' : 'Map unmounted'} />\n        )}\n      </View>\n    </View>\n  );\n}\n","error":"import { ArcgisMapView } from 'expo-arcgis-maps-sdk';\nimport { useState } from 'react';\nimport { Text, View } from 'react-native';\n\nimport type { ScreenProps } from '../constants';\nimport { screenStyles } from '../styles';\n\n/**\n * Exercises the stable error contract deterministically: an unsupported basemap\n * fails TypeScript validation with `E_INVALID_ARGUMENT`, reported via\n * `onMapError` regardless of key or network.\n */\n\nexport function ErrorScreen(_props: ScreenProps) {\n  const [error, setError] = useState('Waiting for error…');\n  return (\n    <View style={screenStyles.fill}>\n      <ArcgisMapView\n        style={screenStyles.fill}\n        map={{ basemap: 'notARealBasemap' as never }}\n        onMapError={({ nativeEvent }) => setError(`${nativeEvent.code}: ${nativeEvent.message}`)}\n      />\n      <Text style={screenStyles.status}>{error}</Text>\n    </View>\n  );\n}\n"};
